/// Maximum registered consensus-key records returned by the operator snapshot.
const CONSENSUS_KEY_RESPONSE_CAP: usize = 128;
#[expect(single_use_lifetimes, reason = "impl Trait requires a named lifetime")]
fn bounded_consensus_key_records<'a>(
    records: impl IntoIterator<Item = &'a ConsensusKeyRecord>,
) -> Vec<ConsensusKeyRecord> {
    let (selected, _) = collect_bounded_ranked_page(
        records
            .into_iter()
            .map(|record| ((Reverse(record.activation_height), &record.id), record)),
        0,
        CONSENSUS_KEY_RESPONSE_CAP,
        CONSENSUS_KEY_RESPONSE_CAP,
    );
    selected.into_iter().cloned().collect()
}
/// GET /v1/sumeragi/consensus-keys — newest registered consensus/committee keys.
#[iroha_futures::telemetry_future]
pub async fn handle_v1_sumeragi_consensus_keys(
    app: &SharedAppState,
    accept: Option<axum::http::HeaderValue>,
) -> Result<Response> {
    let world = app.state.world_view();
    let records =
        bounded_consensus_key_records(world.consensus_keys().iter().map(|(_, record)| record));
    let format = match crate::utils::negotiate_response_format(accept.as_ref()) {
        Ok(fmt) => fmt,
        Err(resp) => return Ok(resp),
    };
    if matches!(format, crate::utils::ResponseFormat::Norito) {
        return Ok(crate::NoritoBody(records).into_response());
    }
    pretty_json_response(&records)
}
#[cfg(test)]
mod consensus_key_response_bounds_tests {
    use super::{CONSENSUS_KEY_RESPONSE_CAP, bounded_consensus_key_records};
    use iroha_crypto::{Algorithm, KeyPair};
    use iroha_data_model::consensus::{
        ConsensusKeyId, ConsensusKeyRecord, ConsensusKeyRole, ConsensusKeyStatus,
    };
    routing_test! { sync consensus_key_snapshot_keeps_only_the_newest_named_protocol_bound
        let public_key = KeyPair::random_with_algorithm(Algorithm::Ed25519)
            .public_key()
            .clone();
        let records: Vec<_> = (0..CONSENSUS_KEY_RESPONSE_CAP + 2)
            .map(|height| ConsensusKeyRecord {
                id: ConsensusKeyId::new(ConsensusKeyRole::Validator, "bounded-key"),
                public_key: public_key.clone(),
                pop: None,
                activation_height: height as u64,
                expiry_height: None,
                hsm: None,
                replaces: None,
                status: ConsensusKeyStatus::Active,
            })
            .collect();
        let selected = bounded_consensus_key_records(&records);
        assert_eq!(selected.len(), CONSENSUS_KEY_RESPONSE_CAP);
        assert_eq!(
            selected.first().map(|record| record.activation_height),
            Some((CONSENSUS_KEY_RESPONSE_CAP + 1) as u64)
        );
        assert_eq!(
            selected.last().map(|record| record.activation_height),
            Some(2)
        );
    }
}
fn query_internal_error(message: impl Into<String>) -> Error {
    Error::Query(iroha_data_model::ValidationFail::InternalError(
        message.into(),
    ))
}
/// Run synchronous query work while retaining admission through physical completion.
pub(crate) async fn run_admitted_blocking<T, F>(
    admission: crate::QueryAdmissionPermit,
    worker_failure: &'static str,
    work: F,
) -> Result<T>
where
    T: Send + 'static,
    F: FnOnce() -> Result<T> + Send + 'static,
{
    tokio::task::spawn_blocking(move || {
        // Keep every owned permit in the physical worker. Dropping or aborting
        // the HTTP future detaches `spawn_blocking`; it must not free capacity
        // while CPU or file work is still running.
        let _admission = admission;
        work()
    })
    .await
    .map_err(|_| query_internal_error(worker_failure))?
}
#[cfg(feature = "app_api")]
async fn run_sccp_submit_blocking<T, F>(worker_failure: &'static str, work: F) -> Result<T>
where
    T: Send + 'static,
    F: FnOnce() -> Result<T> + Send + 'static,
{
    tokio::task::spawn_blocking(work)
        .await
        .map_err(|_| sccp_internal_error(worker_failure))?
}
/// GET /v1/bridge/finality/{height} — Self-contained finality proof for a block.
#[iroha_futures::telemetry_future]
pub(crate) async fn handle_v1_bridge_finality(
    state: Arc<CoreState>,
    height: u64,
    format: crate::utils::ResponseFormat,
    admission: crate::QueryAdmissionPermit,
) -> Result<Response> {
    run_admitted_blocking(
        admission,
        "bridge finality verification worker failed",
        move || {
            let proof = iroha_core::bridge::build_finality_proof(state.as_ref(), height)
                .map_err(map_bridge_finality_error)?;
            if matches!(format, crate::utils::ResponseFormat::Norito) {
                return Ok(crate::NoritoBody(proof).into_response());
            }
            pretty_json_response(&proof)
        },
    )
    .await
}
