    routing_test! { sync query_free_surfaces_reject_every_nonempty_query
        assert!(reject_sccp_query(None).is_ok());
        assert!(reject_sccp_query(Some("")).is_ok());
        for query in [
            "network_id_hex=00",
            "proof_bytes_hex=00",
            "allow_unready=true",
            "destination=ethereum",
            "?",
        ] {
            let error = reject_sccp_query(Some(query)).expect_err("query must reject");
            assert!(
                conversion_message(&error)
                    .is_some_and(|message| message.contains("does not accept query parameters"))
            );
        }
        for valid in [
            None,
            Some(""),
            Some("from=7"),
            Some("limit=50"),
            Some("from=7&limit=50"),
            Some("from=7&after_index=0"),
            Some("from=7&after_index=511&limit=50"),
        ] {
            assert!(validate_sccp_recent_query(valid).is_ok());
        }
        assert_eq!(
            parse_sccp_recent_query(Some("from=7&limit=50"))
                .expect("canonical recent window")
                .from,
            Some(7)
        );
        assert_eq!(
            parse_sccp_recent_query(Some("from=7&limit=50"))
                .expect("canonical recent window")
                .limit,
            Some(50)
        );
        assert_eq!(
            parse_sccp_recent_query(Some("from=7&after_index=12"))
                .expect("canonical compound recent cursor")
                .after_index,
            Some(12)
        );
        for invalid in [
            "network_id_hex=00",
            "proof_bytes_hex=00",
            "allow_unready=true",
            "from=1&from=2",
            "limit=1&limit=2",
            "after_index=0",
            "from=1&after_index=0&after_index=1",
            "from=1&&limit=2",
            "f%72om=1",
            "from=1&",
            "from",
            "from=",
            "from=0",
            "from=01",
            "from=+1",
            "from=%31",
            "from=18446744073709551616",
            "limit=0",
            "limit=51",
            "limit=18446744073709551615",
            "from=1&after_index=512",
            "from=1&after_index=01",
            "from=1&after_index=+1",
        ] {
            assert!(
                validate_sccp_recent_query(Some(invalid)).is_err(),
                "noncanonical recent query must reject: {invalid}"
            );
        }
        let oversized = format!("from=1&limit=1{}", "0".repeat(65));
        assert!(
            parse_sccp_recent_query(Some(&oversized)).is_err(),
            "oversized recent query must reject before generic query decoding"
        );
        let state = empty_taira_state();
        for window in [
            SccpRecentWindowQuery {
                from: Some(0),
                after_index: None,
                limit: Some(1),
            },
            SccpRecentWindowQuery {
                from: Some(1),
                after_index: None,
                limit: Some(0),
            },
            SccpRecentWindowQuery {
                from: Some(1),
                after_index: None,
                limit: Some(51),
            },
            SccpRecentWindowQuery {
                from: None,
                after_index: Some(0),
                limit: Some(1),
            },
        ] {
            assert!(
                collect_recent_sccp_messages(&state, &window).is_err(),
                "direct handler window must enforce SCCP bounds: {window:?}"
            );
        }
    }
