    routing_test! { sync bundle_proof_request_and_recent_readback_survive_body_eviction
        let (state, message_id) = exact_archived_sccp_state();
        let bundle = sccp_message_bundle_for_request(&state, message_id)
            .expect("bodyless bundle lookup")
            .expect("bodyless bundle exists");
        assert_eq!(bundle.commitment.message_id, message_id);
        assert!(
            iroha_sccp::verified_sccp_message_taira_finality_proof_cryptographically_self_consistent(
                &bundle,
            )
            .is_some()
        );
        iroha_sccp::reset_sccp_destination_proof_work_counters_v1();
        let mut material = None;
        for _ in 0..4 {
            material = Some(
                sccp_exact_proof_material(&state, message_id)
                    .expect("bodyless proof-request lookup")
                    .expect("bodyless proof request exists"),
            );
        }
        let material = material.expect("repeated proof construction returns material");
        assert_eq!(
            iroha_sccp::sccp_destination_proof_work_counters_v1().bls_verifications,
            0,
            "Kura-backed proof-request construction must reuse verified finality"
        );
        assert_eq!(material.bundle, bundle);
        assert_eq!(material.indexed.descriptor.commitment_index, 0);
        let finality = iroha_sccp::decode_taira_bridge_finality_proof(&bundle.finality_proof)
            .expect("bodyless bundle finality decodes");
        assert_eq!(finality.block_header.height().get(), 2);
        assert_eq!(
            material.request.public_inputs().finality_block_hash,
            <[u8; 32]>::from(Hash::from(finality.finality_artifact.block_hash))
        );
        let recent = collect_recent_sccp_messages(
            &state,
            &SccpRecentWindowQuery {
                from: None,
                after_index: None,
                limit: Some(1),
            },
        )
        .expect("bodyless recent lookup");
        assert_eq!(recent.items.len(), 1);
        assert_eq!(recent.items[0].commitment_index, 0);
        assert_eq!(recent.items[0].message_id_hex, hex::encode(message_id));
        assert!(recent.next.is_none());
    }
    routing_test! { async registry_endpoint_negotiates_exact_json_and_norito_payloads
        let state = empty_taira_state();
        let json_accept = axum::http::HeaderValue::from_static("application/json");
        let json_response = handle_v1_sccp_registry(&state, Some(json_accept))
            .await
            .expect("registry JSON response");
        assert_eq!(
            json_response
                .headers()
                .get(axum::http::header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("application/json")
        );
        assert_eq!(
            json_response
                .headers()
                .get(axum::http::header::VARY)
                .and_then(|value| value.to_str().ok()),
            Some("Accept")
        );
        let json_bytes = axum::body::to_bytes(json_response.into_body(), usize::MAX)
            .await
            .expect("registry JSON body");
        let json_registry =
            norito::json::from_slice::<iroha_data_model::bridge::SccpRegistryV1>(&json_bytes)
                .expect("typed registry JSON");
        assert_eq!(
            json_registry,
            iroha_data_model::bridge::SccpRegistryV1::default()
        );
        // Torii's first-release API defaults to canonical Norito when the
        // client does not send an explicit Accept preference.
        let norito_response = handle_v1_sccp_registry(&state, None)
            .await
            .expect("registry Norito response");
        assert_eq!(
            norito_response
                .headers()
                .get(axum::http::header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some(crate::utils::NORITO_MIME_TYPE)
        );
        assert_eq!(
            norito_response
                .headers()
                .get(axum::http::header::VARY)
                .and_then(|value| value.to_str().ok()),
            Some("Accept")
        );
        let norito_bytes = axum::body::to_bytes(norito_response.into_body(), usize::MAX)
            .await
            .expect("registry Norito body");
        let norito_registry =
            norito::decode_from_bytes::<iroha_data_model::bridge::SccpRegistryV1>(&norito_bytes)
                .expect("typed registry Norito");
        assert_eq!(norito_registry, json_registry);
    }
