fn build_sccp_finality_proof_bytes(
    finality_proof: &iroha_data_model::bridge::BridgeFinalityProof,
    commitment_root: [u8; 32],
) -> Result<Vec<u8>> {
    let Some(block_root) = finality_proof.block_header.sccp_commitment_root() else {
        return Err(sccp_bad_request(
            "requested Taira block does not anchor an SCCP commitment root",
        ));
    };
    if block_root != commitment_root {
        return Err(sccp_bad_request(
            "requested SCCP commitment root does not match the finalized Taira block header",
        ));
    }
    to_bytes(finality_proof).map_err(|err| {
        sccp_internal_error(format!(
            "failed to encode exact Sumeragi-v2 Taira finality proof: {err}"
        ))
    })
}
fn validate_archived_sccp_message_descriptor(
    indexed: &SccpIndexedOutboundRecord,
    message: &iroha_core::bridge::ValidatedSccpOutboundMessageProjectionV1,
) -> Result<()> {
    if message.commitment_index != indexed.descriptor.commitment_index
        || message.commitment.message_id != indexed.key.message_id
        || message.context.lane != indexed.key.lane
        || message.context.destination_binding_hash != indexed.descriptor.destination_binding_hash
        || message.context.route_configuration_hash != indexed.descriptor.route_configuration_hash
        || message.commitment.payload_hash != indexed.descriptor.payload_hash
    {
        return Err(sccp_internal_error(format!(
            "SCCP message {} disagrees with its authenticated commitment index, lane, binding, route configuration, or payload",
            hex::encode(indexed.key.message_id)
        )));
    }
    Ok(())
}
fn reconstruct_sccp_message_bundles_from_indexed_records(
    state: &CoreState,
    indexed_records: &[SccpIndexedOutboundRecord],
) -> Result<(
    iroha_core::bridge::VerifiedV2FinalityArtifact,
    Vec<TairaSccpMessageProofV1>,
)> {
    let first = indexed_records.first().ok_or_else(|| {
        sccp_internal_error("SCCP bundle reconstruction requires at least one indexed record")
    })?;
    let height = first.descriptor.recorded_at_height;
    if indexed_records
        .iter()
        .any(|indexed| indexed.descriptor.recorded_at_height != height)
    {
        return Err(sccp_internal_error(format!(
            "SCCP proof request mixes records outside height {height}"
        )));
    }
    let finalized = iroha_core::bridge::validated_sccp_finalized_messages_at_height(state, height)
        .map_err(|reason| sccp_internal_error(reason))?
        .ok_or_else(|| {
            sccp_internal_error(format!(
                "SCCP message {} is indexed at height {height}, but the finalized projection is empty",
                hex::encode(first.key.message_id)
            ))
        })?;
    let commitments = finalized
        .messages
        .iter()
        .map(|message| message.commitment.clone())
        .collect::<Vec<_>>();
    let finality_proof_bytes =
        build_sccp_finality_proof_bytes(&finalized.finality_proof, finalized.commitment_root)?;
    let verified_finality = finalized.verified_finality().clone();
    let mut bundles = Vec::with_capacity(indexed_records.len());
    for indexed in indexed_records {
        let index = usize::try_from(indexed.descriptor.commitment_index)
            .expect("bounded SCCP commitment index fits usize");
        let message = finalized.messages.get(index).ok_or_else(|| {
            sccp_internal_error(format!(
                "SCCP message {} names absent commitment index {} at height {height}",
                hex::encode(indexed.key.message_id),
                indexed.descriptor.commitment_index
            ))
        })?;
        validate_archived_sccp_message_descriptor(indexed, message)?;
        if sccp_message_source_domain(&message.payload) != iroha_sccp::SCCP_DOMAIN_SORA {
            return Err(sccp_bad_request(
                "SCCP transparent proof readback is reserved for SORA-origin messages; inbound messages use protocol-native admission",
            ));
        }
        let merkle_proof =
            iroha_sccp::commitment_merkle_proof(&commitments, index).ok_or_else(|| {
                sccp_internal_error(format!(
                    "failed to derive SCCP Merkle proof for message {} at height {height}",
                    hex::encode(indexed.key.message_id)
                ))
            })?;
        bundles.push(TairaSccpMessageProofV1 {
            version: 1,
            commitment_root: finalized.commitment_root,
            commitment: message.commitment.clone(),
            merkle_proof,
            payload: message.payload.clone(),
            finality_proof: finality_proof_bytes.clone(),
        });
    }
    Ok((verified_finality, bundles))
}
fn reconstruct_sccp_message_bundle_from_indexed_record(
    state: &CoreState,
    indexed: SccpIndexedOutboundRecord,
) -> Result<(
    iroha_core::bridge::VerifiedV2FinalityArtifact,
    TairaSccpMessageProofV1,
)> {
    let (verified_finality, mut bundles) = reconstruct_sccp_message_bundles_from_indexed_records(
        state,
        std::slice::from_ref(&indexed),
    )?;
    let bundle = bundles.pop().ok_or_else(|| {
        sccp_internal_error(format!(
            "SCCP message {} produced no reconstructed finalized bundle",
            hex::encode(indexed.key.message_id)
        ))
    })?;
    Ok((verified_finality, bundle))
}
fn sccp_message_bundle_for_request(
    state: &CoreState,
    message_id: [u8; 32],
) -> Result<Option<TairaSccpMessageProofV1>> {
    let Some(indexed) = sccp_indexed_outbound_record(state, message_id)? else {
        return Ok(None);
    };
    reconstruct_sccp_message_bundle_from_indexed_record(state, indexed)
        .map(|(_, bundle)| Some(bundle))
}
fn sccp_committed_outbound_context(
    bundle: &TairaSccpMessageProofV1,
) -> Result<iroha_data_model::bridge::SccpOutboundMessageContextV1> {
    let context = bundle.commitment.context;
    if !context.is_well_formed()
        || sccp_message_source_domain(&bundle.payload) != context.lane.source.domain_id()
        || sccp_message_target_domain(&bundle.payload) != context.lane.target.domain_id()
        || iroha_sccp::hub_commitment_from_sccp_payload(context, &bundle.payload).as_ref()
            != Some(&bundle.commitment)
    {
        return Err(sccp_internal_error(
            "finalized SCCP message bundle disagrees with its exact committed outbound context",
        ));
    }
    Ok(context)
}
fn projection_text_value(value: &SccpNormalizedCodecValueV1) -> Option<String> {
    match value {
        SccpNormalizedCodecValueV1::CanonicalText { value } => Some(value.clone()),
        _ => None,
    }
}
fn recent_message_projection_asset_id(projection: &SccpPayloadProjectionV1) -> Option<String> {
    match projection {
        SccpPayloadProjectionV1::Transfer(item) => projection_text_value(&item.asset_id),
    }
}
fn recent_message_projection_route_id(projection: &SccpPayloadProjectionV1) -> Option<String> {
    match projection {
        SccpPayloadProjectionV1::Transfer(item) => projection_text_value(&item.route_id),
    }
}
fn recent_message_projection_recipient(projection: &SccpPayloadProjectionV1) -> Option<String> {
    match projection {
        SccpPayloadProjectionV1::Transfer(item) => projection_text_value(&item.recipient),
    }
}
fn sccp_quantity_from_atomic_amount(
    amount: u128,
    payload_amount_scale: u32,
    settlement_spec: NumericSpec,
) -> Result<Quantity> {
    if settlement_spec.scale() != Some(payload_amount_scale) {
        return Err(sccp_internal_error(format!(
            "governed SCCP payload scale {payload_amount_scale} disagrees with settlement asset numeric spec {settlement_spec}"
        )));
    }
    let numeric = Numeric::try_new(amount, payload_amount_scale).map_err(|error| {
        sccp_internal_error(format!(
            "SCCP atomic amount cannot be represented at governed scale {payload_amount_scale}: {error}"
        ))
    })?;
    settlement_spec.check(&numeric).map_err(|error| {
        sccp_internal_error(format!(
            "SCCP amount violates the settlement asset numeric spec: {error}"
        ))
    })?;
    Quantity::from_canonical_numeric(numeric).map_err(|error| {
        sccp_internal_error(format!(
            "SCCP atomic amount is not an exact non-negative quantity: {error}"
        ))
    })
}
fn recent_message_projection_amount(
    projection: &SccpPayloadProjectionV1,
    route: &iroha_data_model::bridge::SccpGovernedRouteV1,
    settlement_spec: NumericSpec,
) -> Result<Quantity> {
    let SccpPayloadProjectionV1::Transfer(item) = projection;
    if item.route_revision != route.revision
        || projection_text_value(&item.asset_id).as_deref() != Some(route.asset_key.as_str())
        || projection_text_value(&item.route_id).as_deref() != Some(route.route_id.as_str())
    {
        return Err(sccp_internal_error(
            "finalized SCCP projection disagrees with its retained governed route",
        ));
    }
    sccp_quantity_from_atomic_amount(
        item.amount,
        route.settlement.payload_amount_scale,
        settlement_spec,
    )
}
fn validate_recent_message_projection(
    projection: &SccpPayloadProjectionV1,
    context: iroha_data_model::bridge::SccpOutboundMessageContextV1,
) -> Result<()> {
    let SccpPayloadProjectionV1::Transfer(transfer) = projection;
    let recipient_matches_target = match (context.lane.target, &transfer.recipient) {
        (
            iroha_data_model::bridge::SccpNetworkV1::EthereumMainnet
            | iroha_data_model::bridge::SccpNetworkV1::EthereumSepolia
            | iroha_data_model::bridge::SccpNetworkV1::BscMainnet
            | iroha_data_model::bridge::SccpNetworkV1::BscTestnet,
            SccpNormalizedCodecValueV1::EvmAddress20 { .. },
        )
        | (
            iroha_data_model::bridge::SccpNetworkV1::TronMainnet
            | iroha_data_model::bridge::SccpNetworkV1::TronNile
            | iroha_data_model::bridge::SccpNetworkV1::TronShasta,
            SccpNormalizedCodecValueV1::TronAddress21 { .. },
        )
        | (
            iroha_data_model::bridge::SccpNetworkV1::SolanaTestnet,
            SccpNormalizedCodecValueV1::SolanaPubkey32 { .. },
        )
        | (
            iroha_data_model::bridge::SccpNetworkV1::TonMainnet
            | iroha_data_model::bridge::SccpNetworkV1::TonTestnet,
            SccpNormalizedCodecValueV1::TonAccount36 { .. },
        ) => true,
        _ => false,
    };
    if transfer.version != 1
        || transfer.source_domain != context.lane.source.domain_id()
        || transfer.dest_domain != context.lane.target.domain_id()
        || transfer.route_revision == 0
        || transfer.asset_home_domain != iroha_sccp::SCCP_DOMAIN_SORA
        || transfer.amount == 0
        || !matches!(
            &transfer.sender,
            SccpNormalizedCodecValueV1::CanonicalText { .. }
        )
        || projection_text_value(&transfer.asset_id).is_none()
        || projection_text_value(&transfer.route_id).is_none()
        || !recipient_matches_target
    {
        return Err(sccp_internal_error(
            "finalized SCCP message has an impossible normalized transfer projection",
        ));
    }
    Ok(())
}
fn recent_message_entry_from_projection(
    state: &CoreState,
    indexed: &SccpIndexedOutboundRecord,
    height: u64,
    message_id: [u8; 32],
    message: &iroha_core::bridge::ValidatedSccpOutboundMessageProjectionV1,
) -> Result<SccpRecentMessageDto> {
    let context = message.context;
    if !context.is_well_formed()
        || sccp_message_source_domain(&message.payload) != context.lane.source.domain_id()
        || sccp_message_target_domain(&message.payload) != context.lane.target.domain_id()
        || iroha_sccp::hub_commitment_from_sccp_payload(context, &message.payload).as_ref()
            != Some(&message.commitment)
    {
        return Err(sccp_internal_error(
            "finalized SCCP message disagrees with its exact committed outbound context",
        ));
    }
    if message.commitment.message_id != message_id {
        return Err(sccp_internal_error(
            "validated SCCP outbox projection returned a different message identifier",
        ));
    }
    let message_id_hex = hex::encode(message_id);
    let payload_projection = sccp_payload_projection(&message.payload).ok_or_else(|| {
        sccp_internal_error(format!(
            "finalized SCCP message {message_id_hex} has no valid closed transfer projection"
        ))
    })?;
    validate_recent_message_projection(&payload_projection, context)?;
    let asset_id = recent_message_projection_asset_id(&payload_projection);
    let route_id = recent_message_projection_route_id(&payload_projection);
    let recipient = recent_message_projection_recipient(&payload_projection);
    let registry = state.sccp_registry_snapshot();
    let governed_route = sccp_historical_route_for_record(registry.as_ref(), indexed)?;
    let settlement_spec = state
        .world_view()
        .asset_definition(&governed_route.settlement.asset_definition_id)
        .map_err(|_| {
            sccp_internal_error(format!(
                "retained SCCP route names missing settlement asset definition {}",
                governed_route.settlement.asset_definition_id
            ))
        })?
        .spec();
    let amount =
        recent_message_projection_amount(&payload_projection, governed_route, settlement_spec)?;
    Ok(SccpRecentMessageDto {
        height,
        commitment_index: message.commitment_index,
        message_id_hex: message_id_hex.clone(),
        kind: sccp_message_payload_kind_key(&message.payload).to_owned(),
        source_profile: context.lane.source.profile_key().to_owned(),
        target_profile: context.lane.target.profile_key().to_owned(),
        destination_binding_hash: format!("0x{}", hex::encode(context.destination_binding_hash)),
        route_configuration_hash: format!("0x{}", hex::encode(context.route_configuration_hash)),
        target_domain: context.lane.target.domain_id(),
        asset_id,
        route_id,
        recipient,
        amount,
        payload_projection,
        links: SccpRecentMessageLinksDto {
            bundle_path: format!("/v1/sccp/proofs/message/{message_id_hex}"),
            proof_request_path: format!("/v1/sccp/proof-requests/{message_id_hex}"),
        },
    })
}
fn take_bounded_recent_sccp_index_keys(
    ordered: impl Iterator<Item = iroha_data_model::bridge::SccpOutboundMessageIndexKeyV1>,
    limit: usize,
) -> Vec<iroha_data_model::bridge::SccpOutboundMessageIndexKeyV1> {
    ordered.take(limit).collect()
}
fn recent_sccp_entries_from_indexed_records(
    state: &CoreState,
    indexed_records: &[SccpIndexedOutboundRecord],
) -> Result<Vec<SccpRecentMessageDto>> {
    let mut entries = Vec::with_capacity(indexed_records.len());
    let mut offset = 0;
    while offset < indexed_records.len() {
        let height = indexed_records[offset].descriptor.recorded_at_height;
        let end = indexed_records[offset..]
            .iter()
            .position(|indexed| indexed.descriptor.recorded_at_height != height)
            .map_or(indexed_records.len(), |relative| offset + relative);
        let finalized =
            iroha_core::bridge::validated_sccp_finalized_messages_at_height(state, height)
                .map_err(sccp_internal_error)?
                .ok_or_else(|| {
                    sccp_internal_error(format!(
                        "SCCP recent index at height {height} names an empty finalized projection"
                    ))
                })?;
        for indexed in &indexed_records[offset..end] {
            let index = usize::try_from(indexed.descriptor.commitment_index)
                .expect("bounded SCCP commitment index fits usize");
            let message = finalized.messages.get(index).ok_or_else(|| {
                sccp_internal_error(format!(
                    "SCCP recent message {} names absent commitment index {} at height {height}",
                    hex::encode(indexed.key.message_id),
                    indexed.descriptor.commitment_index,
                ))
            })?;
            validate_archived_sccp_message_descriptor(indexed, message)?;
            if sccp_message_source_domain(&message.payload) != iroha_sccp::SCCP_DOMAIN_SORA {
                return Err(sccp_bad_request(
                    "SCCP recent readback is reserved for SORA-origin messages; inbound messages use protocol-native admission",
                ));
            }
            entries.push(recent_message_entry_from_projection(
                state,
                indexed,
                height,
                indexed.key.message_id,
                message,
            )?);
        }
        offset = end;
    }
    Ok(entries)
}
fn collect_recent_sccp_messages(
    state: &CoreState,
    window: &SccpRecentWindowQuery,
) -> Result<SccpRecentMessagesDto> {
    const RECENT_SCCP_MESSAGES_CAP: usize = 50;
    if window.from == Some(0) {
        return Err(sccp_bad_request(
            "recent SCCP query field `from` must be a positive block height",
        ));
    }
    if window.after_index.is_some() && window.from.is_none() {
        return Err(sccp_bad_request(
            "recent SCCP query field `after_index` requires the paired `from` height",
        ));
    }
    if window.after_index.is_some_and(|index| {
        index >= iroha_data_model::bridge::SCCP_OUTBOUND_MESSAGES_MAX_PER_BLOCK_V1
    }) {
        return Err(sccp_bad_request(format!(
            "recent SCCP query field `after_index` must be between 0 and {}",
            iroha_data_model::bridge::SCCP_OUTBOUND_MESSAGES_MAX_PER_BLOCK_V1 - 1
        )));
    }
    if window
        .limit
        .is_some_and(|limit| !(1..=RECENT_SCCP_MESSAGES_CAP as u64).contains(&limit))
    {
        return Err(sccp_bad_request(format!(
            "recent SCCP query field `limit` must be between 1 and {RECENT_SCCP_MESSAGES_CAP}"
        )));
    }
    let limit = window
        .limit
        .map(|value| usize::try_from(value).expect("bounded SCCP limit fits usize"))
        .unwrap_or(RECENT_SCCP_MESSAGES_CAP);
    let through_height = window.from.unwrap_or(u64::MAX);
    // Reverse-height index ordering makes the range seek logarithmic and the
    // forward scan strictly bounded by `limit`, even when `from` is deep in a
    // large history.
    let selected = {
        let world = state.world_view();
        let start = if let Some(after_index) = window.after_index {
            iroha_data_model::bridge::SccpOutboundMessageIndexKeyV1::range_start_after(
                through_height,
                after_index,
            )
            .ok_or_else(|| sccp_bad_request("invalid SCCP recent compound cursor"))?
        } else {
            iroha_data_model::bridge::SccpOutboundMessageIndexKeyV1::range_start_at_or_before(
                through_height,
            )
        };
        take_bounded_recent_sccp_index_keys(
            world
                .sccp_outbound_message_index()
                .range(start..)
                .map(|(index_key, _)| *index_key),
            limit.saturating_add(1),
        )
    };
    let has_more = selected.len() > limit;
    let mut indexed_records = Vec::with_capacity(selected.len().min(limit));
    for index_key in selected.into_iter().take(limit) {
        let indexed =
            sccp_indexed_outbound_record(state, index_key.message_id)?.ok_or_else(|| {
                sccp_internal_error(format!(
                    "ordered SCCP index names missing global locator {}",
                    hex::encode(index_key.message_id)
                ))
            })?;
        if iroha_data_model::bridge::SccpOutboundMessageIndexKeyV1::from_descriptor(
            indexed.key,
            indexed.descriptor,
        ) != Some(index_key)
        {
            return Err(sccp_internal_error(format!(
                "ordered SCCP index entry {} disagrees with its authoritative outbound record",
                hex::encode(index_key.message_id)
            )));
        }
        indexed_records.push(indexed);
    }
    let items = recent_sccp_entries_from_indexed_records(state, &indexed_records)?;
    if items.len() != indexed_records.len() {
        return Err(sccp_internal_error(
            "SCCP recent-message outbox projection returned an incomplete page",
        ));
    }
    let next = has_more
        .then_some(indexed_records.last())
        .flatten()
        .map(|last| SccpRecentCursorDto {
            from: last.descriptor.recorded_at_height,
            after_index: last.descriptor.commitment_index,
        });
    Ok(SccpRecentMessagesDto { items, next })
}
