fn hash_to_hex<H>(hash: H) -> String
where
    H: AsRef<[u8; iroha_crypto::Hash::LENGTH]>,
{
    hex::encode(hash.as_ref())
}
fn evidence_to_json(rec: &EvidenceRecord) -> Value {
    use iroha_data_model::block::consensus_v2::SumeragiV2Equivocation;
    use norito::codec::Encode as _;
    let evidence = &rec.evidence.equivocation;
    let (class, round, signer, first, second) = match &evidence.conflict {
        SumeragiV2Equivocation::Proposal { first, second } => (
            "proposal",
            first.round,
            first.proposer,
            first.encode(),
            second.encode(),
        ),
        SumeragiV2Equivocation::PhaseVote { first, second } => (
            "phase_vote",
            first.round,
            first.signer,
            first.encode(),
            second.encode(),
        ),
        SumeragiV2Equivocation::TimeoutVote { first, second } => (
            "timeout_vote",
            first.round,
            first.signer,
            first.encode(),
            second.encode(),
        ),
    };
    let mut map = json::Map::new();
    map.insert("kind".into(), Value::from("SumeragiV2Equivocation"));
    map.insert("class".into(), Value::from(class));
    map.insert("height".into(), Value::from(round.height));
    map.insert("view".into(), Value::from(round.view));
    map.insert("epoch".into(), Value::from(evidence.context.epoch));
    map.insert("signer".into(), Value::from(signer));
    map.insert(
        "context_id".into(),
        Value::from(hash_to_hex(round.context_id.0)),
    );
    map.insert(
        "artifact_hash_1".into(),
        Value::from(hex::encode(<[u8; iroha_crypto::Hash::LENGTH]>::from(
            iroha_crypto::Hash::new(first),
        ))),
    );
    map.insert(
        "artifact_hash_2".into(),
        Value::from(hex::encode(<[u8; iroha_crypto::Hash::LENGTH]>::from(
            iroha_crypto::Hash::new(second),
        ))),
    );
    map.insert(
        "recorded_height".into(),
        Value::from(rec.recorded_at_height),
    );
    map.insert("recorded_view".into(), Value::from(rec.recorded_at_view));
    map.insert("recorded_ms".into(), Value::from(rec.recorded_at_ms));
    map.insert(
        "consensus_admitted_height".into(),
        rec.consensus_admitted_at_height
            .map_or(Value::Null, Value::from),
    );
    Value::Object(map)
}
fn reject_direct_multisig_signing(
    state: &CoreState,
    tx: &SignedTransaction,
) -> Option<AcceptTransactionFail> {
    if tx.authority().controller().multisig_policy().is_none() {
        return None;
    }
    if !state.has_account(tx.authority()) {
        return None;
    }
    let only_custom_instruction_envelopes = matches!(
        tx.instructions(),
        Executable::Instructions(items)
            if !items.is_empty()
                && items.iter().all(|instruction| {
                    instruction
                        .as_any()
                        .downcast_ref::<iroha_data_model::isi::CustomInstruction>()
                        .is_some()
                })
    );
    if only_custom_instruction_envelopes {
        return None;
    }
    let rejection = SignatureVerificationFail::new(
        tx.signature().clone(),
        SignatureRejectionCode::UnsupportedAuthority,
        "direct signing with multisig accounts is forbidden; use multisig propose/approve",
    );
    Some(AcceptTransactionFail::SignatureVerification(rejection))
}
#[cfg(test)]
mod multisig_guard_tests {
    use super::*;
    use iroha_core::{
        kura::Kura,
        query::store::LiveQueryStore,
        state::{State, World},
    };
    use iroha_data_model::{
        account::{MultisigMember, MultisigPolicy},
        isi::CustomInstruction,
        role::{Role, RoleId},
    };
    routing_test! { sync direct_multisig_signing_rejected_during_admission
        let domain_id: DomainId = DomainId::try_new("wonderland", "universal").unwrap();
        let signer_keypair = super::checked_routing_fixture_keypair(
            0xe7,
            iroha_crypto::Algorithm::Ed25519,
            "derive direct multisig fixture signer key",
        );
        let policy = MultisigPolicy::new(
            1,
            vec![MultisigMember::new(signer_keypair.public_key().clone(), 1).unwrap()],
        )
        .unwrap();
        let multisig_id = AccountId::new_multisig(policy);
        let domain = Domain::new(domain_id.clone()).build(multisig_id.account());
        let multisig_account =
            Account::new(multisig_id.account().clone()).build(multisig_id.account());
        let world = World::with([domain], [multisig_account], []);
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(world, kura, query_handle);
        let tx = TransactionBuilder::new(
            *state.network_id_ref(),
            multisig_id.clone().into(),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .with_executable(Executable::Instructions(Vec::new().into()))
        .sign(signer_keypair.private_key());
        let rejection = reject_direct_multisig_signing(&state, &tx);
        match rejection {
            Some(AcceptTransactionFail::SignatureVerification(fail)) => {
                assert_eq!(fail.code(), SignatureRejectionCode::UnsupportedAuthority);
            }
            other => panic!("expected multisig direct-sign rejection, got {other:?}"),
        }
    }
    routing_test! { sync single_signatory_with_multisig_role_is_not_rejected
        let domain_id: DomainId = DomainId::try_new("wonderland", "universal").unwrap();
        let signer = super::checked_routing_fixture_keypair(
            0xe8,
            iroha_crypto::Algorithm::Ed25519,
            "derive multisig role fixture signer key",
        );
        let signatory_id = AccountId::new(signer.public_key().clone());
        let role_id: RoleId = "MULTISIG_SIGNATORY/test/0".parse().unwrap();
        let role =
            Role::new(role_id.clone(), signatory_id.clone().into()).build(signatory_id.account());
        let domain = Domain::new(domain_id.clone()).build(signatory_id.account());
        let account = Account::new(signatory_id.account().clone()).build(signatory_id.account());
        let mut world = World::with_assets_and_roles([domain], [account], [], [], [], [role]);
        world.grant_role_for_tests(signatory_id.clone().into(), role_id);
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(world, kura, query_handle);
        let tx = TransactionBuilder::new(
            *state.network_id_ref(),
            signatory_id.clone().into(),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .with_executable(Executable::Instructions(Vec::new().into()))
        .sign(signer.private_key());
        let rejection = reject_direct_multisig_signing(&state, &tx);
        assert!(
            rejection.is_none(),
            "single-signature signatories with multisig role must pass admission guard"
        );
    }
    routing_test! { sync multisig_authority_with_custom_instruction_envelope_is_not_rejected
        let domain_id: DomainId = DomainId::try_new("wonderland", "universal").unwrap();
        let signer_keypair = super::checked_routing_fixture_keypair(
            0xe9,
            iroha_crypto::Algorithm::Ed25519,
            "derive multisig custom-envelope fixture signer key",
        );
        let policy = MultisigPolicy::new(
            1,
            vec![MultisigMember::new(signer_keypair.public_key().clone(), 1).unwrap()],
        )
        .unwrap();
        let multisig_id = AccountId::new_multisig(policy);
        let domain = Domain::new(domain_id.clone()).build(multisig_id.account());
        let multisig_account =
            Account::new(multisig_id.account().clone()).build(multisig_id.account());
        let world = World::with([domain], [multisig_account], []);
        let kura = Kura::blank_kura_for_testing();
        let query_handle = LiveQueryStore::start_test();
        let state = State::new_for_testing(world, kura, query_handle);
        let custom: InstructionBox = CustomInstruction::new("multisig-envelope").into();
        let tx = TransactionBuilder::new(
            *state.network_id_ref(),
            multisig_id.clone().into(),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .with_executable(Executable::Instructions(vec![custom].into()))
        .sign(signer_keypair.private_key());
        let rejection = reject_direct_multisig_signing(&state, &tx);
        assert!(
            rejection.is_none(),
            "multisig custom instruction envelopes must pass admission guard"
        );
    }
}
/// Validate a transaction at Torii ingress and return the accepted form.
pub fn accept_transaction_for_ingress(
    state: Arc<CoreState>,
    tx: impl Into<TransactionEntrypoint>,
    telemetry: &MaybeTelemetry,
) -> Result<iroha_core::tx::AcceptedTransaction<'static>> {
    reject_emergency_fast_transaction_ingress(state.as_ref())?;
    #[cfg(not(feature = "telemetry"))]
    let _ = telemetry;
    #[cfg(feature = "telemetry")]
    let decode_started = std::time::Instant::now();
    let tx = tx.into();
    #[cfg(feature = "telemetry")]
    observe_route_stage_latency(
        telemetry,
        "transaction",
        "decode_or_build",
        "ok",
        decode_started.elapsed(),
    );
    #[cfg(feature = "telemetry")]
    let verify_started = std::time::Instant::now();
    let (max_clock_drift, tx_limits) = state.transaction_admission_limits();
    if let TransactionEntrypoint::External(signed) = &tx
        && let Some(rejection) = reject_direct_multisig_signing(state.as_ref(), signed)
    {
        iroha_logger::warn!(
            authority = %signed.authority(),
            "rejecting transaction directly signed by multisig account"
        );
        #[cfg(feature = "telemetry")]
        telemetry.with_metrics(|tel| {
            tel.inc_torii_multisig_direct_sign_reject();
            let signature_count = signed.signature_count() as u64;
            let signature_limit = tx_limits.max_signatures().get();
            let authority_label = match signed.authority().controller() {
                iroha_data_model::account::AccountController::Single(_) => "single",
                iroha_data_model::account::AccountController::Multisig(_) => "multisig",
            };
            tel.inc_torii_signature_limit_reject(signature_count, signature_limit, authority_label);
        });
        #[cfg(feature = "telemetry")]
        observe_route_stage_latency(
            telemetry,
            "transaction",
            "verify",
            "error",
            verify_started.elapsed(),
        );
        return Err(Error::AcceptTransaction(rejection));
    }
    #[cfg(feature = "telemetry")]
    let (signature_count, signature_limit, authority_label) = match &tx {
        TransactionEntrypoint::External(signed) => {
            let authority_label = match signed.authority().controller() {
                iroha_data_model::account::AccountController::Single(_) => "single",
                iroha_data_model::account::AccountController::Multisig(_) => "multisig",
            };
            (
                signed.signature_count() as u64,
                tx_limits.max_signatures().get(),
                authority_label,
            )
        }
        TransactionEntrypoint::SealedCommitment(_) => {
            (1, tx_limits.max_signatures().get(), "sealed_commitment")
        }
        TransactionEntrypoint::SealedReveal(reveal) => {
            let signed = reveal.signed_transaction();
            let authority_label = match signed.authority().controller() {
                iroha_data_model::account::AccountController::Single(_) => "single",
                iroha_data_model::account::AccountController::Multisig(_) => "multisig",
            };
            (
                signed.signature_count() as u64,
                tx_limits.max_signatures().get(),
                authority_label,
            )
        }
        TransactionEntrypoint::Time(_) => (0, tx_limits.max_signatures().get(), "time"),
    };
    let crypto_cfg = state.crypto();
    let network_id = *state.network_id_ref();
    match iroha_core::tx::AcceptedTransaction::accept_entrypoint(
        tx,
        &network_id,
        max_clock_drift,
        tx_limits,
        crypto_cfg.as_ref(),
    ) {
        Ok(tx) => {
            #[cfg(feature = "telemetry")]
            observe_route_stage_latency(
                telemetry,
                "transaction",
                "verify",
                "ok",
                verify_started.elapsed(),
            );
            Ok(tx)
        }
        Err(err) => {
            iroha_logger::warn!(?err, "transaction rejected during admission");
            #[cfg(feature = "telemetry")]
            telemetry.with_metrics(|tel| {
                if let AcceptTransactionFail::TransactionLimit(limit) = &err {
                    if limit.reason.starts_with(SIGNATURE_LIMIT_REASON_PREFIX) {
                        tel.inc_torii_signature_limit_reject(
                            signature_count,
                            signature_limit,
                            authority_label,
                        );
                    }
                }
                if matches!(err, AcceptTransactionFail::NetworkTimeUnhealthy { .. }) {
                    tel.inc_torii_nts_unhealthy_reject();
                }
            });
            #[cfg(feature = "telemetry")]
            observe_route_stage_latency(
                telemetry,
                "transaction",
                "verify",
                "error",
                verify_started.elapsed(),
            );
            Err(Error::AcceptTransaction(err))
        }
    }
}
/// Validate an already decoded signed transaction at Torii ingress.
pub fn accept_decoded_signed_transaction_for_ingress(
    state: Arc<CoreState>,
    tx: DecodedVersionedSignedTransaction,
    telemetry: &MaybeTelemetry,
) -> Result<iroha_core::tx::AcceptedTransaction<'static>> {
    accept_decoded_signed_transaction_for_ingress_with_precheck(state, tx, telemetry, false, None)
}
/// Validate an already decoded signed transaction at Torii ingress after Ed25519 precheck.
pub fn accept_decoded_signed_transaction_for_ingress_with_precheck(
    state: Arc<CoreState>,
    tx: DecodedVersionedSignedTransaction,
    telemetry: &MaybeTelemetry,
    single_ed25519_prechecked: bool,
    precheck_rejection: Option<AcceptTransactionFail>,
) -> Result<iroha_core::tx::AcceptedTransaction<'static>> {
    reject_emergency_fast_transaction_ingress(state.as_ref())?;
    #[cfg(not(feature = "telemetry"))]
    let _ = telemetry;
    #[cfg(feature = "telemetry")]
    let decode_started = std::time::Instant::now();
    #[cfg(feature = "telemetry")]
    observe_route_stage_latency(
        telemetry,
        "transaction",
        "decode_or_build",
        "ok",
        decode_started.elapsed(),
    );
    #[cfg(feature = "telemetry")]
    let verify_started = std::time::Instant::now();
    let (max_clock_drift, tx_limits) = state.transaction_admission_limits();
    if let Some(rejection) = reject_direct_multisig_signing(state.as_ref(), tx.signed()) {
        iroha_logger::warn!(
            authority = %tx.authority(),
            "rejecting transaction directly signed by multisig account"
        );
        #[cfg(feature = "telemetry")]
        telemetry.with_metrics(|tel| {
            tel.inc_torii_multisig_direct_sign_reject();
            let signature_count = tx.signed().signature_count() as u64;
            let signature_limit = tx_limits.max_signatures().get();
            let authority_label = match tx.authority().controller() {
                iroha_data_model::account::AccountController::Single(_) => "single",
                iroha_data_model::account::AccountController::Multisig(_) => "multisig",
            };
            tel.inc_torii_signature_limit_reject(signature_count, signature_limit, authority_label);
        });
        #[cfg(feature = "telemetry")]
        observe_route_stage_latency(
            telemetry,
            "transaction",
            "verify",
            "error",
            verify_started.elapsed(),
        );
        return Err(Error::AcceptTransaction(rejection));
    }
    #[cfg(feature = "telemetry")]
    let (signature_count, signature_limit, authority_label) = {
        let authority_label = match tx.authority().controller() {
            iroha_data_model::account::AccountController::Single(_) => "single",
            iroha_data_model::account::AccountController::Multisig(_) => "multisig",
        };
        (
            tx.signed().signature_count() as u64,
            tx_limits.max_signatures().get(),
            authority_label,
        )
    };
    let crypto_cfg = state.crypto();
    let network_id = *state.network_id_ref();
    let accepted = if let Some(err) = precheck_rejection {
        Err(err)
    } else if single_ed25519_prechecked {
        tx.into_accepted_after_single_ed25519_precheck(
            &network_id,
            max_clock_drift,
            tx_limits,
            crypto_cfg.as_ref(),
        )
    } else {
        tx.into_accepted(&network_id, max_clock_drift, tx_limits, crypto_cfg.as_ref())
    };
    match accepted {
        Ok(tx) => {
            #[cfg(feature = "telemetry")]
            observe_route_stage_latency(
                telemetry,
                "transaction",
                "verify",
                "ok",
                verify_started.elapsed(),
            );
            Ok(tx)
        }
        Err(err) => {
            iroha_logger::warn!(?err, "transaction rejected during admission");
            #[cfg(feature = "telemetry")]
            telemetry.with_metrics(|tel| {
                if let AcceptTransactionFail::TransactionLimit(limit) = &err {
                    if limit.reason.starts_with(SIGNATURE_LIMIT_REASON_PREFIX) {
                        tel.inc_torii_signature_limit_reject(
                            signature_count,
                            signature_limit,
                            authority_label,
                        );
                    }
                }
                if matches!(err, AcceptTransactionFail::NetworkTimeUnhealthy { .. }) {
                    tel.inc_torii_nts_unhealthy_reject();
                }
            });
            #[cfg(feature = "telemetry")]
            observe_route_stage_latency(
                telemetry,
                "transaction",
                "verify",
                "error",
                verify_started.elapsed(),
            );
            Err(Error::AcceptTransaction(err))
        }
    }
}
pub(crate) fn push_accepted_transaction_for_ingress(
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    accepted_tx: iroha_core::tx::AcceptedTransaction<'static>,
) -> Result<RoutingDecision> {
    push_accepted_transaction_for_ingress_with_routing_plan(queue, state, accepted_tx, None)
}
pub(crate) fn reject_ingress_if_queue_capacity_saturated(
    queue: &Queue,
    state: &CoreState,
    incoming_tx_count: usize,
) -> Result<()> {
    if incoming_tx_count == 0 {
        return Ok(());
    }
    reject_emergency_fast_transaction_ingress(state)?;
    let pressure = {
        let block_time = state.sumeragi_block_cadence();
        queue.refresh_pressure_budget_from_block_time(block_time)
    };
    let count_room = pressure
        .capacity
        .get()
        .saturating_sub(pressure.tracked_tx_count);
    let incoming_retained_floor =
        Queue::retained_byte_cost_floor_for_transactions(incoming_tx_count);
    let saturated_by_count = pressure.saturated_by_count || incoming_tx_count > count_room;
    let saturated_by_bytes = pressure.saturated_by_bytes
        || pressure
            .retained_bytes
            .saturating_add(incoming_retained_floor)
            > pressure.max_retained_bytes.get();
    if !saturated_by_count && !saturated_by_bytes {
        return Ok(());
    }
    iroha_logger::debug!(
        incoming_tx_count,
        queued = pressure.queued_tx_count,
        tracked = pressure.tracked_tx_count,
        capacity = pressure.capacity.get(),
        retained_bytes = pressure.retained_bytes,
        max_retained_bytes = pressure.max_retained_bytes.get(),
        saturated_by_count,
        saturated_by_bytes,
        "rejecting transaction ingress before admission because queue capacity is saturated"
    );
    Err(Error::PushIntoQueue {
        source: Box::new(queue::Error::Full),
        backpressure: queue::BackpressureState::Saturated {
            queued: pressure.queued_tx_count,
            capacity: pressure.capacity,
        },
    })
}
fn reject_emergency_fast_transaction_ingress(state: &CoreState) -> Result<()> {
    if state.emergency_fast_startup_enabled() {
        return Err(Error::AppServiceUnavailable {
            code: "emergency_fast_transaction_ingress_disabled",
            message: "transaction admission and validation are disabled in emergency Fast mode; restart in Strict mode before submitting transactions"
                .to_owned(),
        });
    }
    Ok(())
}
pub(crate) fn push_accepted_transaction_for_ingress_with_routing_plan(
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    accepted_tx: iroha_core::tx::AcceptedTransaction<'static>,
    routing_plan: Option<RoutingPlan>,
) -> Result<RoutingDecision> {
    push_accepted_transaction_for_ingress_with_durability(
        queue,
        state,
        accepted_tx,
        routing_plan.map_or(IngressRouting::Derived, IngressRouting::Planned),
    )
}
pub(crate) fn push_accepted_transaction_for_ingress_with_routing_plan_strict_durable(
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    accepted_tx: iroha_core::tx::AcceptedTransaction<'static>,
    routing_plan: RoutingPlan,
) -> Result<RoutingDecision> {
    push_accepted_transaction_for_ingress_with_durability(
        queue,
        state,
        accepted_tx,
        IngressRouting::StrictDurable(routing_plan),
    )
}
pub(crate) fn push_accepted_transaction_for_ingress_with_routing_plan_strict_durable_claim(
    queue: Arc<Queue>,
    state: Arc<CoreState>,
    accepted_tx: iroha_core::tx::AcceptedTransaction<'static>,
    routing_plan: RoutingPlan,
    expected_admission_binding: &iroha_core::torii_proxy::QueuePlanAdmissionBindingV1,
) -> Result<queue::QueuePlanDurableAdmissionV1> {
    let pressure = {
        let block_time = state.sumeragi_block_cadence();
        queue.refresh_pressure_budget_from_block_time(block_time)
    };
    if pressure.saturated_by_age {
        iroha_logger::debug!(
            tx_hash = %accepted_tx.hash(),
            queued = pressure.queued_tx_count,
            tracked = pressure.tracked_tx_count,
            capacity = pressure.capacity.get(),
            oldest_queued_tx_age_ms = pressure.oldest_queued_tx_age_ms,
            "local queue is latency-saturated; keeping strict durable ingress open until capacity is exhausted"
        );
    }
    queue
        .push_with_lane_with_state_and_routing_plan_strict_global_admission_claim(
            accepted_tx,
            state.as_ref(),
            routing_plan,
            expected_admission_binding,
        )
        .map_err(|queue::Failure { tx, err }| {
            if matches!(err, queue::Error::Full) {
                iroha_logger::debug!(
                    tx_hash = %tx.as_ref().hash(),
                    "queue rejected strict durable transaction due to backpressure"
                );
            } else {
                iroha_logger::warn!(
                    tx_hash = %tx.as_ref().hash(),
                    ?err,
                    "failed to durably admit transaction with an exact queue-plan claim"
                );
            }
            drop(tx);
            (err, queue.current_backpressure())
        })
        .map_err(|(err, backpressure)| Error::PushIntoQueue {
            source: Box::new(err),
            backpressure,
        })
        .inspect(|claim| {
            let route = claim.routing_plan.coordinator_route();
            iroha_logger::debug!(
                lane = route.lane_id.as_u32(),
                dataspace = route.dataspace_id.as_u64(),
                authority_height = claim.context.authority_height,
                proposal_height = claim.context.proposal_height,
                "transaction enqueued with a durable queue-plan admission claim"
            );
        })
}
