async fn fetch_network_time_snapshot() -> iroha_core::time::NetworkTimeAdmissionSnapshot {
    match task::spawn_blocking(iroha_core::time::admission_snapshot).await {
        Ok(snapshot) => snapshot,
        Err(join_err) => {
            iroha_logger::warn!(
                ?join_err,
                "Failed to fetch network time snapshot off-thread; retrying inline"
            );
            iroha_core::time::admission_snapshot()
        }
    }
}
/// Network Time Service: return current network time snapshot.
pub async fn handle_time_now() -> impl IntoResponse {
    let snapshot = fetch_network_time_snapshot().await;
    let s = snapshot.status;
    let now_ms: u64 = s
        .now
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
        .try_into()
        .unwrap_or(0);
    let mut obj = norito::json::Map::new();
    obj.insert("now".into(), norito::json::Value::from(now_ms));
    obj.insert("offset_ms".into(), norito::json::Value::from(s.offset_ms));
    obj.insert(
        "confidence_ms".into(),
        norito::json::Value::from(s.confidence_ms),
    );
    obj.insert(
        "sample_count".into(),
        norito::json::Value::from(s.sample_count as u64),
    );
    obj.insert(
        "peer_count".into(),
        norito::json::Value::from(s.peer_count as u64),
    );
    obj.insert(
        "enforcement_mode".into(),
        norito::json::Value::from(snapshot.enforcement_mode.as_str()),
    );
    obj.insert("fallback".into(), norito::json::Value::from(s.fallback));
    let mut health = norito::json::Map::new();
    health.insert(
        "healthy".into(),
        norito::json::Value::from(s.health.healthy),
    );
    health.insert(
        "min_samples_ok".into(),
        norito::json::Value::from(s.health.min_samples_ok),
    );
    health.insert(
        "offset_ok".into(),
        norito::json::Value::from(s.health.offset_ok),
    );
    health.insert(
        "confidence_ok".into(),
        norito::json::Value::from(s.health.confidence_ok),
    );
    obj.insert("health".into(), norito::json::Value::Object(health));
    infallible_pretty_json_response(&obj, "{}")
}
/// Network Time Service diagnostics.
pub async fn handle_time_status() -> impl IntoResponse {
    let mut obj = norito::json::Map::new();
    let diagnostics = tokio::task::spawn_blocking(iroha_core::time::diagnostics_snapshot)
        .await
        .unwrap_or_else(|join_err| {
            iroha_logger::warn!(
                ?join_err,
                "Failed to fetch atomic network time diagnostics; retrying inline"
            );
            iroha_core::time::diagnostics_snapshot()
        });
    let iroha_core::time::NetworkTimeDiagnostics {
        status,
        samples: snapshot,
        rtt: rtt_snapshot,
        enforcement_mode,
        running,
    } = diagnostics;
    obj.insert(
        "peers".into(),
        norito::json::Value::from(status.peer_count as u64),
    );
    obj.insert(
        "samples_used".into(),
        norito::json::Value::from(status.sample_count as u64),
    );
    obj.insert(
        "offset_ms".into(),
        norito::json::Value::from(status.offset_ms),
    );
    obj.insert(
        "confidence_ms".into(),
        norito::json::Value::from(status.confidence_ms),
    );
    obj.insert(
        "enforcement_mode".into(),
        norito::json::Value::from(enforcement_mode.as_str()),
    );
    obj.insert(
        "fallback".into(),
        norito::json::Value::from(status.fallback),
    );
    let mut health = norito::json::Map::new();
    health.insert(
        "healthy".into(),
        norito::json::Value::from(status.health.healthy),
    );
    health.insert(
        "min_samples_ok".into(),
        norito::json::Value::from(status.health.min_samples_ok),
    );
    health.insert(
        "offset_ok".into(),
        norito::json::Value::from(status.health.offset_ok),
    );
    health.insert(
        "confidence_ok".into(),
        norito::json::Value::from(status.health.confidence_ok),
    );
    obj.insert("health".into(), norito::json::Value::Object(health));
    let samples = snapshot
        .into_iter()
        .map(|(peer, offset_ms, rtt_ms, count)| {
            let mut o = norito::json::Map::new();
            o.insert("peer".into(), norito::json::Value::from(peer));
            o.insert(
                "last_offset_ms".into(),
                norito::json::Value::from(offset_ms),
            );
            o.insert("last_rtt_ms".into(), norito::json::Value::from(rtt_ms));
            o.insert("count".into(), norito::json::Value::from(count as u64));
            norito::json::Value::Object(o)
        })
        .collect::<Vec<_>>();
    obj.insert("samples".into(), norito::json::Value::Array(samples));
    // RTT histogram snapshot
    let mut buckets = Vec::new();
    for (le, cnt) in rtt_snapshot
        .bounds_ms
        .iter()
        .zip(rtt_snapshot.bucket_counts.iter())
    {
        let mut b = norito::json::Map::new();
        b.insert("le".into(), norito::json::Value::from(*le));
        b.insert("count".into(), norito::json::Value::from(*cnt));
        buckets.push(norito::json::Value::Object(b));
    }
    let mut rtt = norito::json::Map::new();
    rtt.insert("buckets".into(), norito::json::Value::Array(buckets));
    rtt.insert(
        "sum_ms".into(),
        norito::json::Value::from(rtt_snapshot.sum_ms),
    );
    rtt.insert(
        "count".into(),
        norito::json::Value::from(rtt_snapshot.count),
    );
    obj.insert("rtt".into(), norito::json::Value::Object(rtt));
    let note = if running {
        "NTS running"
    } else {
        "NTS stopped"
    };
    obj.insert("note".into(), norito::json::Value::from(note));
    infallible_pretty_json_response(&obj, "{}")
}
