    routing_test! { async asset_transfer_control_get_returns_stored_state_and_usage
        let authority =
            checked_multisig_selector_account_id(0x70, "derive asset-transfer authority key");
        let domain_id: DomainId = DomainId::try_new("banka", "universal").expect("domain");
        let scoped_account_id = checked_multisig_selector_account_id(
            0x71,
            "derive asset-transfer controlled account key",
        );
        let controlled_account_id: dm::AccountId = scoped_account_id.clone().into();
        let asset_definition_id = test_asset_definition_id();
        let definition = dm::AssetDefinition::numeric(
            asset_definition_id.clone(),
            "asset_transfer_control".to_owned(),
            iroha_data_model::asset::AssetBalancePolicy::Global,
            None,
        )
        .build(&authority);
        let domain = Domain::new(domain_id).build(&authority);
        let record = dm::AssetTransferControlRecord {
            asset_definition_id: asset_definition_id.clone(),
            availability_revision: 5,
            incoming_availability: dm::AssetTransferAvailability::Disabled,
            outgoing_availability: dm::AssetTransferAvailability::Enabled,
            availability_reason: Some("inbound review".to_owned()),
            blacklisted: false,
            holding_limit: Some(1_000_u32.into()),
            limits: vec![
                dm::AssetTransferLimit {
                    window: dm::AssetTransferControlWindow::Day,
                    cap_amount: Some(100_u32.into()),
                },
                dm::AssetTransferLimit {
                    window: dm::AssetTransferControlWindow::Week,
                    cap_amount: Some(500_u32.into()),
                },
            ],
            usages: vec![dm::AssetTransferUsageBucket {
                window: dm::AssetTransferControlWindow::Day,
                bucket_start_ms: 1_700_000_000_000,
                spent_amount: 25_u32.into(),
            }],
            updated_at_ms: Some(1_700_000_100_000),
        };
        let mut metadata = Metadata::default();
        metadata.insert(
            Name::from_str(dm::ASSET_TRANSFER_CONTROL_METADATA_KEY).expect("metadata key"),
            IrohaJson::new(dm::AssetTransferControlStoreV1 {
                controls: vec![record],
            }),
        );
        let account = Account::new(scoped_account_id.account().clone())
            .with_metadata(metadata)
            .build(&authority);
        let state = build_state(World::with([domain], [account], [definition]));
        let JsonBody(response) = handle_post_asset_transfer_control_get(
            state,
            NoritoJson(AssetTransferControlGetRequestDto {
                account_id: controlled_account_id,
                asset_definition_id,
            }),
        )
        .await
        .expect("load stored control");
        assert_eq!(response.control.availability_revision, 5);
        assert_eq!(
            response.control.incoming,
            dm::AssetTransferAvailability::Disabled
        );
        assert_eq!(
            response.control.outgoing,
            dm::AssetTransferAvailability::Enabled
        );
        assert_eq!(
            response.control.availability_reason.as_deref(),
            Some("inbound review")
        );
        assert!(!response.control.blacklisted);
        assert_eq!(response.control.limits.len(), 2);
        assert_eq!(response.control.limits[0].window, "DAY");
        assert_eq!(
            response.control.limits[0].cap_amount.as_ref(),
            Some(&Quantity::from(100_u32))
        );
        assert_eq!(response.usages.len(), 1);
        assert_eq!(response.usages[0].window, "DAY");
        assert_eq!(response.usages[0].spent_amount, Quantity::from(25_u32));
        assert_eq!(
            response.usages[0].cap_amount.as_ref(),
            Some(&Quantity::from(100_u32))
        );
        assert_eq!(
            response.usages[0].bucket_start,
            format_unix_timestamp_ms_rfc3339(1_700_000_000_000).expect("bucket start")
        );
        assert_eq!(
            response.control.updated_at.as_deref(),
            Some(
                format_unix_timestamp_ms_rfc3339(1_700_000_100_000)
                    .expect("updated at")
                    .as_str()
            )
        );
    }
