fn contract_payload_digest_hex(payload: Option<&IrohaJson>) -> String {
    let canonical = payload
        .and_then(|value| norito::json::to_json(value).ok())
        .unwrap_or_default();
    hex::encode(blake3_hash(canonical.as_bytes()).as_bytes())
}
