    #[cfg(feature = "app_api")]
    async fn register_manifest_handler_accepts_request() {
        let manifest = default_manifest();
        let (queue, state, telemetry) = handler_context(|_| {});
        let transaction = transaction_from_manifest(*state.network_id_ref(), &manifest);
        let expected_tx_hash = hex::encode(transaction.hash().as_ref());
        let resp = handle_post_sorafs_register_manifest(queue, state, telemetry, transaction)
            .await
            .expect("handler ok")
            .into_response();
        assert_eq!(resp.status(), axum::http::StatusCode::ACCEPTED);
        let bytes = http_body_util::BodyExt::collect(resp.into_body())
            .await
            .unwrap()
            .to_bytes();
        let v: norito::json::Value = norito::json::from_slice(&bytes).unwrap();
        let expected_digest = hex::encode(manifest.digest().expect("manifest digest").as_bytes());
        assert_eq!(
            v.get("manifest_digest_hex")
                .and_then(norito::json::Value::as_str),
            Some(expected_digest.as_str())
        );
        assert_eq!(
            v.get("tx_hash_hex").and_then(norito::json::Value::as_str),
            Some(expected_tx_hash.as_str())
        );
        assert_eq!(
            v.get("status").and_then(norito::json::Value::as_str),
            Some("submitted")
        );
        assert_eq!(
            v.as_object().map(|object| object.len()),
            Some(3),
            "admission response must not claim pre-finality fees, custody, or pin status"
        );
    }
