    routing_test! { sync filter_result_ok_eq_matches
        // NOTE: For app-facing filters on transactions, empty-instruction Externals are
        // treated as logically-ok for filtering purposes, even if a dummy error is set
        // in the test transaction. This keeps filtering aligned with projections used
        // by integration tests which don’t execute instructions.
        let (a, kp) = account_with_key();
        let tx_true = make_external_tx(&a, &kp, 100, None, true);
        let tx_false = make_external_tx(&a, &kp, 100, None, false);
        let expr_true = crate::filter::FilterExpr::Eq(
            crate::filter::FieldPath("result_ok".into()),
            norito::json::Value::Bool(true),
        );
        assert!(filter_tx(&expr_true, &tx_true));
        assert!(filter_tx(&expr_true, &tx_false));
        let expr_false = crate::filter::FilterExpr::Eq(
            crate::filter::FieldPath("result_ok".into()),
            norito::json::Value::Bool(false),
        );
        assert!(!filter_tx(&expr_false, &tx_false));
        assert!(!filter_tx(&expr_false, &tx_true));
    }
    routing_test! { sync filter_not_and_or_across_fields
        let (a, kp_a) = account_with_key();
        let (b, kp_b) = account_with_key();
        let tx_a = make_external_tx(&a, &kp_a, 1500, None, true);
        let tx_b = make_external_tx(&b, &kp_b, 900, None, true);
        let tx_c = make_external_tx(&b, &kp_b, 2500, None, false);
        // NOT(authority == a) OR timestamp_ms > 2000
        let expr = crate::filter::FilterExpr::Or(vec![
            crate::filter::FilterExpr::Not(Box::new(crate::filter::FilterExpr::Eq(
                crate::filter::FieldPath("authority".into()),
                norito::json::Value::String(a.to_string()),
            ))),
            crate::filter::FilterExpr::Gt(
                crate::filter::FieldPath("timestamp_ms".into()),
                norito::json::Value::from(2000u64),
            ),
        ]);
        // tx_a should fail (authority==a and ts=1500), tx_b should pass (authority!=a), tx_c should pass (ts>2000)
        assert!(!filter_tx(&expr, &tx_a));
        assert!(filter_tx(&expr, &tx_b));
        assert!(filter_tx(&expr, &tx_c));
    }
    routing_test! { sync kaigi_signal_from_transaction_extracts_metadata
        let (authority, keypair) = account_with_key();
        let mut metadata = dm::Metadata::default();
        metadata.insert(
            "kaigi_signal".parse().expect("metadata key"),
            Json::new(crate::json_object(vec![
                crate::json_entry("schema", "iroha-demo-kaigi-chain-signal/v1"),
                crate::json_entry("callId", "kaigi.universal:weekly-sync"),
                crate::json_entry("call_id", "kaigi.universal:weekly-sync"),
                crate::json_entry("signalKind", "answer"),
                crate::json_entry("signal_kind", "answer"),
                crate::json_entry("hostAccountId", authority.to_string()),
                crate::json_entry("host_account_id", authority.to_string()),
                crate::json_entry("participantAccountId", authority.to_string()),
                crate::json_entry("participant_account_id", authority.to_string()),
                crate::json_entry("createdAtMs", 1_700_000_000_000_u64),
                crate::json_entry("created_at_ms", 1_700_000_000_000_u64),
                crate::json_entry(
                    "encryptedSignal",
                    crate::json_object(vec![crate::json_entry(
                        "schema",
                        "iroha-demo-kaigi-sealed-box/v1",
                    )]),
                ),
            ])),
        );
        let tx = make_external_tx_with_metadata(
            &authority,
            &keypair,
            1_700_000_000_100,
            None,
            true,
            metadata,
        );
        let signal = kaigi_signal_from_transaction(&tx, true, 1_700_000_000_100)
            .expect("signal should parse");
        let authority_literal = authority.to_string();
        assert_eq!(signal.call_id, "kaigi.universal:weekly-sync");
        assert_eq!(signal.signal_kind, "answer");
        assert_eq!(signal.created_at_ms, 1_700_000_000_000);
        assert_eq!(signal.timestamp_ms, Some(1_700_000_000_100));
        assert_eq!(
            signal.authority.as_deref(),
            Some(authority_literal.as_str())
        );
        assert_eq!(
            signal.participant_account_id.as_deref(),
            Some(authority_literal.as_str())
        );
        let response_metadata: Value = signal
            .metadata
            .try_into_any_norito()
            .expect("signal response metadata");
        for key in [
            "hostAccountId",
            "host_account_id",
            "participantAccountId",
            "participant_account_id",
        ] {
            assert_eq!(
                response_metadata.get(key).and_then(Value::as_str),
                Some(authority_literal.as_str()),
                "transparent signal metadata must preserve {key}",
            );
        }
    }
    routing_test! { sync kaigi_signal_from_transaction_normalizes_open_signal_kind
        let (authority, keypair) = account_with_key();
        let signal_metadata = |signal_kind: Option<&str>| {
            let mut fields = vec![
                crate::json_entry("schema", KAIGI_SIGNAL_SCHEMA_V1),
                crate::json_entry("callId", "kaigi.universal:weekly-sync"),
                crate::json_entry("createdAtMs", 1_700_000_000_000_u64),
            ];
            if let Some(signal_kind) = signal_kind {
                fields.push(crate::json_entry("signalKind", signal_kind));
            }
            let mut metadata = dm::Metadata::default();
            metadata.insert(
                "kaigi_signal".parse().expect("metadata key"),
                Json::new(crate::json_object(fields)),
            );
            metadata
        };

        let defaulted = make_external_tx_with_metadata(
            &authority,
            &keypair,
            1_700_000_000_100,
            None,
            true,
            signal_metadata(None),
        );
        assert_eq!(
            kaigi_signal_from_transaction(&defaulted, true, 1_700_000_000_100)
                .expect("missing signal kind should use the canonical default")
                .signal_kind,
            "signal",
        );

        for open_kind in [
            "offer",
            "answer",
            "ice",
            "signal",
            "vendor.signal",
            "信号",
            "\0",
            "\u{feff}signal",
        ] {
            let transaction = make_external_tx_with_metadata(
                &authority,
                &keypair,
                1_700_000_000_100,
                None,
                true,
                signal_metadata(Some(open_kind)),
            );
            assert_eq!(
                kaigi_signal_from_transaction(&transaction, true, 1_700_000_000_100)
                    .expect("open signal kind should project")
                    .signal_kind,
                open_kind,
            );
        }

        let mixed_case = make_external_tx_with_metadata(
            &authority,
            &keypair,
            1_700_000_000_100,
            None,
            true,
            signal_metadata(Some("AnSwEr")),
        );
        assert_eq!(
            kaigi_signal_from_transaction(&mixed_case, true, 1_700_000_000_100)
                .expect("signal kind should retain the documented ASCII case normalization")
                .signal_kind,
            "answer",
        );

        for malformed in ["", " answer ", "\t", "\u{0085}answer", "answer\u{3000}"] {
            let transaction = make_external_tx_with_metadata(
                &authority,
                &keypair,
                1_700_000_000_100,
                None,
                true,
                signal_metadata(Some(malformed)),
            );
            assert!(
                kaigi_signal_from_transaction(&transaction, true, 1_700_000_000_100).is_none(),
                "non-canonical signal kind must fail closed",
            );
        }
    }
    routing_test! { sync kaigi_signal_from_transaction_rejects_conflicting_aliases
        let (authority, keypair) = account_with_key();
        for (label, conflicting_alias) in [
            (
                "call id",
                crate::json_entry("call_id", "kaigi.universal:other-call"),
            ),
            ("signal kind", crate::json_entry("signal_kind", "offer")),
            (
                "creation time",
                crate::json_entry("created_at_ms", 1_700_000_000_001_u64),
            ),
            (
                "host account",
                crate::json_entry("host_account_id", "conflicting-host"),
            ),
            (
                "participant account",
                crate::json_entry("participant_account_id", "conflicting-participant"),
            ),
        ] {
            let mut fields = vec![
                crate::json_entry("schema", KAIGI_SIGNAL_SCHEMA_V1),
                crate::json_entry("callId", "kaigi.universal:weekly-sync"),
                crate::json_entry("signalKind", "answer"),
                crate::json_entry("createdAtMs", 1_700_000_000_000_u64),
                crate::json_entry("hostAccountId", authority.to_string()),
                crate::json_entry("participantAccountId", authority.to_string()),
            ];
            fields.push(conflicting_alias);
            let mut metadata = dm::Metadata::default();
            metadata.insert(
                "kaigi_signal".parse().expect("metadata key"),
                Json::new(crate::json_object(fields)),
            );
            let transaction = make_external_tx_with_metadata(
                &authority,
                &keypair,
                1_700_000_000_100,
                None,
                true,
                metadata,
            );
            assert!(
                kaigi_signal_from_transaction(&transaction, true, 1_700_000_000_100).is_none(),
                "conflicting {label} aliases must fail closed",
            );
            assert!(
                kaigi_signal_from_transaction(&transaction, false, 1_700_000_000_100).is_none(),
                "private projection must also reject conflicting {label} aliases",
            );
        }
    }
