/// GET /v1/sumeragi/status — latest authoritative Sumeragi v2 snapshot.
///
/// The legacy status shape is archival-only. Until the v2 runner publishes a
/// replayed reducer snapshot, fail closed instead of exposing v1/RBC state as
/// though it described the live consensus protocol.
#[iroha_futures::telemetry_future]
pub async fn handle_v1_sumeragi_status(
    State(_state): State<std::sync::Arc<CoreState>>,
    accept: Option<axum::http::HeaderValue>,
    restart_required: bool,
) -> Result<Response> {
    let format = match crate::utils::negotiate_response_format(accept.as_ref()) {
        Ok(format) => format,
        Err(response) => return Ok(response),
    };
    let Some(status) = sumeragi::status::v2_status_with_restart_required(restart_required) else {
        return Ok(StatusCode::SERVICE_UNAVAILABLE.into_response());
    };
    Ok(crate::utils::respond_with_format(status, format))
}
fn sumeragi_pipeline_execution_status(
    snapshot: sumeragi::status::PipelineExecutionSnapshot,
) -> SumeragiPipelineExecutionStatus {
    SumeragiPipelineExecutionStatus {
        tx_vertices_total: snapshot.tx_vertices_total,
        tx_edges_total: snapshot.tx_edges_total,
        overlay_count_total: snapshot.overlay_count_total,
        overlay_instr_total: snapshot.overlay_instr_total,
        overlay_bytes_total: snapshot.overlay_bytes_total,
        rbc_chunks_total: snapshot.rbc_chunks_total,
        rbc_bytes_total: snapshot.rbc_bytes_total,
        detached_prepared_total: snapshot.detached_prepared_total,
        detached_merged_total: snapshot.detached_merged_total,
        detached_fallback_total: snapshot.detached_fallback_total,
        detached_fallback_fee_postprocessing_total: snapshot
            .detached_fallback_fee_postprocessing_total,
        detached_fallback_user_executor_total: snapshot.detached_fallback_user_executor_total,
        detached_fallback_durable_state_total: snapshot.detached_fallback_durable_state_total,
        detached_fallback_unsupported_instruction_total: snapshot
            .detached_fallback_unsupported_instruction_total,
        detached_fallback_rejected_eval_total: snapshot.detached_fallback_rejected_eval_total,
        detached_fallback_overlay_error_total: snapshot.detached_fallback_overlay_error_total,
        quarantine_executed_total: snapshot.quarantine_executed_total,
    }
}
fn sumeragi_npos_diagnostics(
    params: &iroha_data_model::parameter::system::SumeragiNposParameters,
    reducer: &iroha_data_model::block::consensus_v2::SumeragiV2Status,
) -> Result<SumeragiNposDiagnostics> {
    let diagnostics = SumeragiNposDiagnostics {
        epoch_length_blocks: params.epoch_length_blocks(),
        epoch_seed: params.epoch_seed(),
        prf_height: reducer.height,
        prf_view: reducer.view,
    };
    diagnostics.validate().map_err(|reason| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            reason.to_owned(),
        ))
    })?;
    Ok(diagnostics)
}
/// GET `/v1/sumeragi/diagnostics` — non-authoritative operator and lane diagnostics.
#[iroha_futures::telemetry_future]
pub async fn handle_v1_sumeragi_diagnostics(
    State(state): State<std::sync::Arc<CoreState>>,
    durable_queue: Option<std::sync::Arc<Queue>>,
    accept: Option<axum::http::HeaderValue>,
) -> Result<Response> {
    let format = match crate::utils::negotiate_response_format(accept.as_ref()) {
        Ok(format) => format,
        Err(response) => return Ok(response),
    };
    let snapshot = sumeragi::status_snapshot();
    let queue = sumeragi::status::tx_queue_backpressure();
    let world = state.world_view();
    let npos = match world.sumeragi_npos_parameters() {
        Some(params) => {
            let Some(reducer) = sumeragi::status::v2_status() else {
                return Ok(StatusCode::SERVICE_UNAVAILABLE.into_response());
            };
            Some(sumeragi_npos_diagnostics(&params, &reducer)?)
        }
        None => None,
    };
    drop(world);
    let native_amx_participant_applications = state
        .native_amx_participant_applications_diagnostics()
        .map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
                "failed to derive Native AMX participant diagnostics: {error}",
            )))
        })?;
    let durable_lane_diagnostics = state.durable_lane_diagnostics();
    let autonomous_lane_executions = Option::as_ref(&durable_queue)
        .map_or_else(
            || state.autonomous_lane_execution_diagnostics(),
            |queue| state.autonomous_lane_execution_diagnostics_with_queue(queue),
        )
        .map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
                "failed to derive autonomous lane execution diagnostics: {error}",
            )))
        })?;
    let lane_commitments = snapshot
        .lane_commitments
        .iter()
        .map(|entry| SumeragiLaneCommitment {
            block_height: entry.block_height,
            lane_id: entry.lane_id.into(),
            tx_count: entry.tx_count,
            total_chunks: entry.total_chunks,
            rbc_bytes_total: entry.rbc_bytes_total,
            teu_total: entry.teu_total,
            block_hash: entry.block_hash,
        })
        .collect();
    let dataspace_commitments = snapshot
        .dataspace_commitments
        .iter()
        .map(|entry| SumeragiDataspaceCommitment {
            block_height: entry.block_height,
            lane_id: entry.lane_id.into(),
            dataspace_id: entry.dataspace_id.into(),
            tx_count: entry.tx_count,
            total_chunks: entry.total_chunks,
            rbc_bytes_total: entry.rbc_bytes_total,
            teu_total: entry.teu_total,
            block_hash: entry.block_hash,
        })
        .collect();
    let lane_governance = snapshot
        .lane_governance
        .iter()
        .map(|entry| SumeragiLaneGovernance {
            lane_id: entry.lane_id.into(),
            alias: entry.alias.clone(),
            governance: entry.governance.clone(),
            manifest_required: entry.manifest_required,
            manifest_ready: entry.manifest_ready,
            manifest_path: entry.manifest_path.clone(),
            validator_ids: entry.validator_ids.clone(),
            quorum: entry.quorum,
            protected_namespaces: entry.protected_namespaces.clone(),
            runtime_upgrade: entry.runtime_upgrade.as_ref().map(|hook| {
                SumeragiRuntimeUpgradeHook {
                    allow: hook.allow,
                    require_metadata: hook.require_metadata,
                    metadata_key: hook.metadata_key.clone(),
                    allowed_ids: hook.allowed_ids.clone(),
                }
            }),
        })
        .collect();
    let diagnostics = SumeragiDiagnosticsStatus {
        pipeline_execution: sumeragi_pipeline_execution_status(snapshot.pipeline_execution),
        tx_queue_depth: queue.depth,
        tx_queue_capacity: queue.capacity,
        tx_queue_retained_bytes: queue.retained_bytes,
        tx_queue_max_retained_bytes: queue.max_retained_bytes,
        tx_queue_saturated: queue.saturated,
        tx_queue_saturated_by_count: queue.saturated_by_count,
        tx_queue_saturated_by_bytes: queue.saturated_by_bytes,
        tx_queue_saturated_by_age: queue.saturated_by_age,
        tx_queue_oldest_queued_age_ms: queue.oldest_queued_age_ms,
        npos,
        lane_commitments,
        dataspace_commitments,
        lane_settlement_commitments: snapshot.lane_settlement_commitments,
        lane_relay_envelopes: snapshot.lane_relay_envelopes,
        lane_payload_ownerships: durable_lane_diagnostics.lane_payload_ownerships,
        committed_lane_blocks: durable_lane_diagnostics
            .committed_lane_blocks
            .iter()
            .map(committed_lane_block_wire)
            .collect(),
        lane_block_sessions: durable_lane_diagnostics.lane_block_sessions,
        lane_governance_sealed_total: snapshot.lane_governance_sealed_total,
        lane_governance_sealed_aliases: snapshot.lane_governance_sealed_aliases,
        lane_governance,
        native_amx_participant_applications,
        autonomous_lane_executions,
    };
    diagnostics
        .validate_native_amx_participant_applications()
        .map_err(|reason| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(
                reason.to_owned(),
            ))
        })?;
    diagnostics
        .validate_autonomous_lane_executions()
        .map_err(|reason| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(
                reason.to_owned(),
            ))
        })?;
    Ok(crate::utils::respond_with_format(diagnostics, format))
}
/// SSE stream for `/v1/sumeragi/status/sse` using only authoritative v2 snapshots.
///
/// Before reducer replay completes the stream remains silent instead of
/// emitting the archival v1/RBC status shape.
pub fn handle_v1_sumeragi_status_sse(
    _state: std::sync::Arc<CoreState>,
    poll_ms: u64,
    sumeragi_handle: Option<iroha_core::sumeragi::SumeragiHandle>,
) -> Sse<impl futures::Stream<Item = Result<SseEvent, Infallible>>> {
    let interval = Duration::from_millis(poll_ms.max(100));
    let ticker = tokio::time::interval(interval);
    let stream = stream::unfold(
        (ticker, sumeragi_handle),
        |(mut ticker, sumeragi_handle)| async move {
            loop {
                ticker.tick().await;
                let restart_required = sumeragi_handle
                    .as_ref()
                    .is_some_and(iroha_core::sumeragi::SumeragiHandle::restart_required);
                if let Some(status) =
                    sumeragi::status::v2_status_with_restart_required(restart_required)
                {
                    match norito::json::to_json(&status) {
                        Ok(body) => {
                            let event = SseEvent::default().data(body);
                            break Some((Ok(event), (ticker, sumeragi_handle)));
                        }
                        Err(error) => {
                            iroha_logger::error!(
                                ?error,
                                "failed to serialize authoritative Sumeragi v2 status"
                            );
                        }
                    }
                }
            }
        },
    );
    Sse::new(stream)
}
/// Map an `EventBox` into a compact JSON object used by SSE/WS tests.
pub fn event_to_json_value(ev: &iroha_data_model::events::EventBox) -> norito::json::Value {
    use iroha_data_model::events::pipeline::PipelineEventBox;
    use norito::json::{Map, Value};
    let pipeline_event_json = |p: &PipelineEventBox| match p {
        PipelineEventBox::Transaction(t) => {
            let mut m = Map::new();
            m.insert("category".into(), Value::from("Pipeline"));
            m.insert("event".into(), Value::from("Transaction"));
            m.insert("hash".into(), Value::from(format!("{}", t.hash)));
            m.insert("lane_id".into(), Value::from(u64::from(t.lane_id.as_u32())));
            m.insert("dataspace_id".into(), Value::from(t.dataspace_id.as_u64()));
            if let Some(h) = t.block_height {
                m.insert("block_height".into(), Value::from(h.get()));
            } else {
                m.insert("block_height".into(), Value::Null);
            }
            m.insert("status".into(), Value::from(format!("{:?}", t.status)));
            Value::Object(m)
        }
        PipelineEventBox::Block(b) => {
            let mut m = Map::new();
            m.insert("category".into(), Value::from("Pipeline"));
            m.insert("event".into(), Value::from("Block"));
            m.insert("status".into(), Value::from(format!("{:?}", b.status)));
            Value::Object(m)
        }
        PipelineEventBox::Warning(w) => {
            let mut m = Map::new();
            m.insert("category".into(), Value::from("Pipeline"));
            m.insert("event".into(), Value::from("Warning"));
            m.insert("kind".into(), Value::from(w.kind.clone()));
            m.insert("details".into(), Value::from(w.details.clone()));
            // include minimal header info
            m.insert("height".into(), Value::from(w.header.height().get()));
            Value::Object(m)
        }
        PipelineEventBox::Merge(m) => {
            let mut map = Map::new();
            map.insert("category".into(), Value::from("Pipeline"));
            map.insert("event".into(), Value::from("MergeLedger"));
            map.insert("epoch_id".into(), Value::from(m.entry.epoch_id));
            map.insert(
                "global_state_root".into(),
                Value::from(m.entry.global_state_root.to_string()),
            );
            Value::Object(map)
        }
        PipelineEventBox::Witness(w) => {
            let mut map = Map::new();
            map.insert("category".into(), Value::from("Pipeline"));
            map.insert("event".into(), Value::from("Witness"));
            map.insert(
                "block_hash".into(),
                Value::from(format!("{}", w.block_hash)),
            );
            map.insert("height".into(), Value::from(w.height));
            map.insert("view".into(), Value::from(w.view));
            map.insert("epoch".into(), Value::from(w.epoch));
            map.insert(
                "read_count".into(),
                Value::from(w.witness.reads.len() as u64),
            );
            map.insert(
                "write_count".into(),
                Value::from(w.witness.writes.len() as u64),
            );
            Value::Object(map)
        }
    };
    match ev {
        iroha_data_model::events::EventBox::Pipeline(p) => pipeline_event_json(p),
        iroha_data_model::events::EventBox::PipelineBatch(batch) => {
            Value::Array(batch.iter().map(pipeline_event_json).collect())
        }
        iroha_data_model::events::EventBox::Data(d) => {
            use iroha_data_model::prelude as de;
            match d.as_ref() {
                de::DataEvent::Proof(pe) => match pe {
                    iroha_data_model::events::data::proof::ProofEvent::Verified(v) => {
                        let mut m = Map::new();
                        m.insert("category".into(), Value::from("Data"));
                        m.insert("event".into(), Value::from("ProofVerified"));
                        m.insert("backend".into(), Value::from(format!("{}", v.id.backend)));
                        m.insert(
                            "proof_hash".into(),
                            Value::from(hex::encode(v.id.proof_hash)),
                        );
                        if let Some(ch) = v.call_hash {
                            m.insert("call_hash".into(), Value::from(hex::encode(ch)));
                        } else {
                            m.insert("call_hash".into(), Value::Null);
                        }
                        if let Some(eh) = v.envelope_hash {
                            m.insert("envelope_hash".into(), Value::from(hex::encode(eh)));
                        } else {
                            m.insert("envelope_hash".into(), Value::Null);
                        }
                        // Optional vk_ref (backend::name) and vk_commitment (hex)
                        if let Some(vk) = &v.vk_ref {
                            m.insert(
                                "vk_ref".into(),
                                Value::from(format!("{}::{}", vk.backend, vk.name)),
                            );
                        } else {
                            m.insert("vk_ref".into(), Value::Null);
                        }
                        if let Some(comm) = v.vk_commitment {
                            m.insert("vk_commitment".into(), Value::from(hex::encode(comm)));
                        } else {
                            m.insert("vk_commitment".into(), Value::Null);
                        }
                        Value::Object(m)
                    }
                    iroha_data_model::events::data::proof::ProofEvent::Rejected(r) => {
                        let mut m = Map::new();
                        m.insert("category".into(), Value::from("Data"));
                        m.insert("event".into(), Value::from("ProofRejected"));
                        m.insert("backend".into(), Value::from(format!("{}", r.id.backend)));
                        m.insert(
                            "proof_hash".into(),
                            Value::from(hex::encode(r.id.proof_hash)),
                        );
                        if let Some(ch) = r.call_hash {
                            m.insert("call_hash".into(), Value::from(hex::encode(ch)));
                        } else {
                            m.insert("call_hash".into(), Value::Null);
                        }
                        if let Some(eh) = r.envelope_hash {
                            m.insert("envelope_hash".into(), Value::from(hex::encode(eh)));
                        } else {
                            m.insert("envelope_hash".into(), Value::Null);
                        }
                        if let Some(vk) = &r.vk_ref {
                            m.insert(
                                "vk_ref".into(),
                                Value::from(format!("{}::{}", vk.backend, vk.name)),
                            );
                        } else {
                            m.insert("vk_ref".into(), Value::Null);
                        }
                        if let Some(comm) = r.vk_commitment {
                            m.insert("vk_commitment".into(), Value::from(hex::encode(comm)));
                        } else {
                            m.insert("vk_commitment".into(), Value::Null);
                        }
                        Value::Object(m)
                    }
                    iroha_data_model::events::data::proof::ProofEvent::Pruned(p) => {
                        let mut m = Map::new();
                        m.insert("category".into(), Value::from("Data"));
                        m.insert("event".into(), Value::from("ProofPruned"));
                        m.insert("backend".into(), Value::from(p.backend.clone()));
                        m.insert("removed_count".into(), Value::from(p.removed.len() as u64));
                        m.insert("remaining".into(), Value::from(p.remaining));
                        m.insert("cap".into(), Value::from(p.cap));
                        m.insert("grace_blocks".into(), Value::from(p.grace_blocks));
                        m.insert("prune_batch".into(), Value::from(p.prune_batch));
                        m.insert("pruned_at_height".into(), Value::from(p.pruned_at_height));
                        m.insert("pruned_by".into(), Value::from(format!("{}", p.pruned_by)));
                        m.insert("origin".into(), Value::from(format!("{:?}", p.origin)));
                        let removed: Vec<Value> = p
                            .removed
                            .iter()
                            .map(|pid| {
                                let mut e = Map::new();
                                e.insert("backend".into(), Value::from(pid.backend.clone()));
                                e.insert(
                                    "proof_hash".into(),
                                    Value::from(hex::encode(pid.proof_hash)),
                                );
                                Value::Object(e)
                            })
                            .collect();
                        m.insert("removed".into(), Value::Array(removed));
                        Value::Object(m)
                    }
                },
                _ => {
                    let mut m = Map::new();
                    m.insert("category".into(), Value::from("Data"));
                    m.insert("summary".into(), Value::from(format!("{:?}", d)));
                    Value::Object(m)
                }
            }
        }
        _ => {
            let mut m = Map::new();
            m.insert("category".into(), Value::from("Other"));
            m.insert("summary".into(), Value::from(format!("{:?}", ev)));
            Value::Object(m)
        }
    }
}
app_api_items! {
fn event_filters_from_expr(expr: &FilterExpr) -> Vec<EventFilterBox> {
    // Build filters for SSE using available typed filter boxes.
    // Supported fields/operators:
    // - tx_status == {Queued|Expired|Approved|Rejected}
    // - tx_hash == <hex>
    // - tx_block_height == <u64> (non-zero)
    // - block_status == {Created|Approved|Rejected|Committed|Applied}
    // - block_height == <u64> (non-zero)
    // - IsNull(tx_block_height) → only transactions without a block height
    // AND combines compatible fields into a single typed filter; OR unions filters.
    use FilterExpr as F;
    #[derive(Clone)]
    enum PF {
        Tx(TransactionEventFilter),
        Block(BlockEventFilter),
    }
    fn merge(a: PF, b: PF) -> Option<PF> {
        match (a, b) {
            (PF::Tx(mut x), PF::Tx(y)) => {
                if let Some(st) = y.status() {
                    x = x.for_status(st.clone());
                }
                if let Some(h) = y.block_height {
                    x = x.for_block_height(h);
                }
                if let Some(hash) = y.hash() {
                    x = x.for_hash(hash.clone());
                }
                Some(PF::Tx(x))
            }
            (PF::Block(mut x), PF::Block(y)) => {
                if let Some(st) = y.status() {
                    x = x.for_status(st.clone());
                }
                if let Some(h) = y.height() {
                    x = x.for_height(h);
                }
                Some(PF::Block(x))
            }
            _ => None, // incompatible types in AND => no single event can satisfy
        }
    }
    fn to_event_boxes(pfs: Vec<PF>) -> Vec<EventFilterBox> {
        pfs.into_iter()
            .map(|pf| match pf {
                PF::Tx(f) => EventFilterBox::Pipeline(f.into()),
                PF::Block(f) => EventFilterBox::Pipeline(f.into()),
            })
            .collect()
    }
    fn build(expr: &FilterExpr) -> Vec<PF> {
        match expr {
            F::Eq(field, value) => match field.0.as_str() {
                // Transaction fields
                "tx_status" => value
                    .as_str()
                    .and_then(parse_tx_status)
                    .map(|st| vec![PF::Tx(TransactionEventFilter::new().for_status(st))])
                    .unwrap_or_default(),
                "tx_hash" => value
                    .as_str()
                    .and_then(|s| {
                        s.parse::<iroha_crypto::HashOf<
                            iroha_data_model::transaction::signed::SignedTransaction,
                        >>()
                        .ok()
                    })
                    .map(|h| vec![PF::Tx(TransactionEventFilter::new().for_hash(h))])
                    .unwrap_or_default(),
                "tx_block_height" => value
                    .as_u64()
                    .and_then(NonZeroU64::new)
                    .map(|h| {
                        vec![PF::Tx(
                            TransactionEventFilter::new().for_block_height(Some(h)),
                        )]
                    })
                    .unwrap_or_default(),
                "tx_lane_id" => {
                    let lane_raw = value
                        .as_u64()
                        .and_then(|raw| u32::try_from(raw).ok())
                        .or_else(|| value.as_str().and_then(|s| s.parse::<u32>().ok()));
                    lane_raw
                        .map(|raw| {
                            vec![PF::Tx(
                                TransactionEventFilter::new().for_lane_id(LaneId::new(raw)),
                            )]
                        })
                        .unwrap_or_default()
                }
                "tx_dataspace_id" => {
                    let dataspace_raw = value
                        .as_u64()
                        .or_else(|| value.as_str().and_then(|s| s.parse::<u64>().ok()));
                    dataspace_raw
                        .map(|raw| {
                            vec![PF::Tx(
                                TransactionEventFilter::new()
                                    .for_dataspace_id(DataSpaceId::new(raw)),
                            )]
                        })
                        .unwrap_or_default()
                }
                // Block fields
                "block_status" => value
                    .as_str()
                    .and_then(parse_block_status)
                    .map(|st| vec![PF::Block(BlockEventFilter::new().for_status(st))])
                    .unwrap_or_default(),
                "block_height" => value
                    .as_u64()
                    .and_then(NonZeroU64::new)
                    .map(|h| vec![PF::Block(BlockEventFilter::new().for_height(h))])
                    .unwrap_or_default(),
                _ => Vec::new(),
            },
            F::IsNull(field) if field.0.as_str() == "tx_block_height" => {
                vec![PF::Tx(TransactionEventFilter::new().for_block_height(None))]
            }
            F::In(field, list) if field.0.as_str() == "tx_status" => {
                let mut acc = Vec::new();
                for v in list {
                    if let Some(st) = v.as_str().and_then(parse_tx_status) {
                        acc.push(PF::Tx(TransactionEventFilter::new().for_status(st)));
                    }
                }
                acc
            }
            // Combine all children with AND semantics for compatible types
            F::And(children) => {
                let mut acc: Vec<PF> = vec![];
                for c in children {
                    let next = build(c);
                    if acc.is_empty() {
                        acc = next;
                    } else {
                        let mut merged = Vec::new();
                        for a in &acc {
                            for b in &next {
                                if let Some(m) = merge(a.clone(), b.clone()) {
                                    merged.push(m);
                                }
                            }
                        }
                        acc = merged;
                    }
                }
                acc
            }
            // OR = union (list treated as any-of)
            F::Or(children) => {
                let mut acc = Vec::new();
                for c in children {
                    acc.extend(build(c));
                }
                acc
            }
            // Limited NOT support: negate simple status equals by expanding to all other statuses
            F::Not(inner) => match &**inner {
                F::Eq(f, v) if f.0.as_str() == "tx_status" => {
                    let mut acc = Vec::new();
                    if let Some(target) = v.as_str().and_then(parse_tx_status) {
                        use iroha_data_model::events::pipeline::TransactionStatus as TS;
                        let rejected = TS::Rejected(Box::new(
                            iroha_data_model::transaction::error::TransactionRejectionReason::Validation(
                                iroha_data_model::ValidationFail::InternalError("filtered".into()),
                            ),
                        ));
                        let all = [TS::Queued, TS::Expired, TS::Approved, rejected];
                        for st in all.into_iter() {
                            if core::mem::discriminant(&st) != core::mem::discriminant(&target) {
                                acc.push(PF::Tx(TransactionEventFilter::new().for_status(st)));
                            }
                        }
                    }
                    acc
                }
                F::Eq(f, v) if f.0.as_str() == "block_status" => {
                    let mut acc = Vec::new();
                    if let Some(target) = v.as_str().and_then(parse_block_status) {
                        use iroha_data_model::events::pipeline::BlockStatus as BS;
                        let all = [
                            BS::Created,
                            BS::Approved,
                            BS::Rejected(
                                iroha_data_model::block::error::BlockRejectionReason::ConsensusBlockRejection,
                            ),
                            BS::Committed,
                            BS::Applied,
                        ];
                        for st in all.into_iter() {
                            if core::mem::discriminant(&st) != core::mem::discriminant(&target) {
                                acc.push(PF::Block(BlockEventFilter::new().for_status(st)));
                            }
                        }
                    }
                    acc
                }
                _ => Vec::new(),
            },
            _ => Vec::new(),
        }
    }
    to_event_boxes(build(expr))
}
#[derive(Debug, Default, Clone)]
struct SseFilterSpec {
    filters: Option<Arc<Vec<EventFilterBox>>>,
    proof_backend: Option<Vec<String>>,
    proof_call_hash: Option<Vec<[u8; 32]>>,
    proof_envelope_hash: Option<Vec<[u8; 32]>>,
}
fn sse_filter_error(msg: impl Into<String>) -> crate::Error {
    crate::Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::Conversion(msg.into()),
    ))
}
fn parse_sse_filter_params(raw: Option<&str>) -> Result<SseFilterSpec, crate::Error> {
    let Some(raw) = raw else {
        return Ok(SseFilterSpec::default());
    };
    let expr = norito::json::from_str::<FilterExpr>(raw)
        .map_err(|_| sse_filter_error("invalid filter expression"))?;
    parse_sse_filters(&expr).map_err(sse_filter_error)
}
fn parse_sse_filters(expr: &FilterExpr) -> Result<SseFilterSpec, String> {
    #[derive(Default)]
    struct SseFilterUsage {
        event_filter_seen: bool,
        proof_backend: Vec<String>,
        proof_call_hash: Vec<[u8; 32]>,
        proof_envelope_hash: Vec<[u8; 32]>,
    }
    fn parse_u64_value(value: &norito::json::Value) -> Option<u64> {
        value
            .as_u64()
            .or_else(|| value.as_str().and_then(|s| s.parse::<u64>().ok()))
    }
    fn parse_hex_32(field: &str, value: &norito::json::Value) -> Result<[u8; 32], String> {
        let s = value
            .as_str()
            .ok_or_else(|| format!("{field} must be a hex string"))?;
        if s.len() != 64 {
            return Err(format!("{field} must be 64 hex characters"));
        }
        let bytes = hex::decode(s).map_err(|_| format!("{field} must be valid hex"))?;
        if bytes.len() != 32 {
            return Err(format!("{field} must decode to 32 bytes"));
        }
        let mut arr = [0u8; 32];
        arr.copy_from_slice(&bytes);
        Ok(arr)
    }
    fn validate_eq(
        field: &str,
        value: &norito::json::Value,
        usage: &mut SseFilterUsage,
    ) -> Result<(), String> {
        match field {
            "tx_status" => {
                let raw = value
                    .as_str()
                    .ok_or_else(|| "tx_status must be a string".to_string())?;
                if parse_tx_status(raw).is_none() {
                    return Err("tx_status is not a valid status".to_string());
                }
                usage.event_filter_seen = true;
            }
            "tx_hash" => {
                let raw = value
                    .as_str()
                    .ok_or_else(|| "tx_hash must be a string".to_string())?;
                let parsed =
                    raw.parse::<iroha_crypto::HashOf<
                        iroha_data_model::transaction::signed::SignedTransaction,
                    >>();
                if parsed.is_err() {
                    return Err("tx_hash must be a valid hex hash".to_string());
                }
                usage.event_filter_seen = true;
            }
            "tx_block_height" => {
                let raw = parse_u64_value(value)
                    .ok_or_else(|| "tx_block_height must be an unsigned integer".to_string())?;
                if NonZeroU64::new(raw).is_none() {
                    return Err("tx_block_height must be > 0".to_string());
                }
                usage.event_filter_seen = true;
            }
            "tx_lane_id" => {
                let raw = parse_u64_value(value)
                    .ok_or_else(|| "tx_lane_id must be an unsigned integer".to_string())?;
                u32::try_from(raw).map_err(|_| "tx_lane_id must fit in u32".to_string())?;
                usage.event_filter_seen = true;
            }
            "tx_dataspace_id" => {
                let raw = parse_u64_value(value)
                    .ok_or_else(|| "tx_dataspace_id must be an unsigned integer".to_string())?;
                let _ = raw;
                usage.event_filter_seen = true;
            }
            "block_status" => {
                let raw = value
                    .as_str()
                    .ok_or_else(|| "block_status must be a string".to_string())?;
                if parse_block_status(raw).is_none() {
                    return Err("block_status is not a valid status".to_string());
                }
                usage.event_filter_seen = true;
            }
            "block_height" => {
                let raw = parse_u64_value(value)
                    .ok_or_else(|| "block_height must be an unsigned integer".to_string())?;
                if NonZeroU64::new(raw).is_none() {
                    return Err("block_height must be > 0".to_string());
                }
                usage.event_filter_seen = true;
            }
            "proof_backend" => {
                let raw = value
                    .as_str()
                    .ok_or_else(|| "proof_backend must be a string".to_string())?;
                if raw.trim().is_empty() {
                    return Err("proof_backend must be non-empty".to_string());
                }
                usage.proof_backend.push(raw.to_string());
            }
            "proof_call_hash" => {
                let arr = parse_hex_32("proof_call_hash", value)?;
                usage.proof_call_hash.push(arr);
            }
            "proof_envelope_hash" => {
                let arr = parse_hex_32("proof_envelope_hash", value)?;
                usage.proof_envelope_hash.push(arr);
            }
            _ => return Err(format!("unsupported filter field: {field}")),
        }
        Ok(())
    }
    fn validate_in(
        field: &str,
        values: &[norito::json::Value],
        usage: &mut SseFilterUsage,
    ) -> Result<(), String> {
        if values.is_empty() {
            return Err(format!("{field} IN must not be empty"));
        }
        for value in values {
            validate_eq(field, value, usage)?;
        }
        Ok(())
    }
    fn validate_expr(expr: &FilterExpr, usage: &mut SseFilterUsage) -> Result<(), String> {
        match expr {
            FilterExpr::And(list) | FilterExpr::Or(list) => {
                if list.is_empty() {
                    return Err("filter expression must not be empty".to_string());
                }
                for sub in list {
                    validate_expr(sub, usage)?;
                }
            }
            FilterExpr::Not(inner) => match inner.as_ref() {
                FilterExpr::Eq(field, value)
                    if field.0 == "tx_status" || field.0 == "block_status" =>
                {
                    validate_eq(&field.0, value, usage)?;
                }
                _ => {
                    return Err("not only supports tx_status or block_status".to_string());
                }
            },
            FilterExpr::Eq(field, value) => validate_eq(&field.0, value, usage)?,
            FilterExpr::In(field, values) => validate_in(&field.0, values, usage)?,
            FilterExpr::IsNull(field) => {
                if field.0.as_str() != "tx_block_height" {
                    return Err("isnull only supports tx_block_height".to_string());
                }
                usage.event_filter_seen = true;
            }
            _ => return Err("unsupported filter operator".to_string()),
        }
        Ok(())
    }
    let mut usage = SseFilterUsage::default();
    validate_expr(expr, &mut usage)?;
    let filters = event_filters_from_expr(expr);
    if usage.event_filter_seen && filters.is_empty() {
        return Err("filter does not match any SSE events".to_string());
    }
    let filters = if filters.is_empty() {
        None
    } else {
        Some(Arc::new(filters))
    };
    let proof_backend = if usage.proof_backend.is_empty() {
        None
    } else {
        Some(usage.proof_backend)
    };
    let proof_call_hash = if usage.proof_call_hash.is_empty() {
        None
    } else {
        Some(usage.proof_call_hash)
    };
    let proof_envelope_hash = if usage.proof_envelope_hash.is_empty() {
        None
    } else {
        Some(usage.proof_envelope_hash)
    };
    Ok(SseFilterSpec {
        filters,
        proof_backend,
        proof_call_hash,
        proof_envelope_hash,
    })
}
#[cfg(all(test, feature = "app_api"))]
mod sse_filter_validation_tests {
    use super::*;
    use crate::filter::{FieldPath, FilterExpr};
    routing_test! { sync sse_filter_rejects_unknown_field
        let expr = FilterExpr::Eq(
            FieldPath("unknown_field".into()),
            norito::json::Value::String("nope".into()),
        );
        let err = parse_sse_filters(&expr).expect_err("unknown field should be rejected");
        assert!(err.contains("unsupported filter field"));
    }
    routing_test! { sync sse_filter_rejects_invalid_proof_hash
        let expr = FilterExpr::Eq(
            FieldPath("proof_call_hash".into()),
            norito::json::Value::String("deadbeef".into()),
        );
        let err = parse_sse_filters(&expr).expect_err("invalid proof hash should be rejected");
        assert!(err.contains("proof_call_hash"));
    }
    routing_test! { sync sse_filter_rejects_incompatible_and
        let expr = FilterExpr::And(vec![
            FilterExpr::Eq(
                FieldPath("tx_status".into()),
                norito::json::Value::String("Queued".into()),
            ),
            FilterExpr::Eq(
                FieldPath("block_status".into()),
                norito::json::Value::String("Committed".into()),
            ),
        ]);
        let err = parse_sse_filters(&expr).expect_err("incompatible AND should be rejected");
        assert_eq!(err, "filter does not match any SSE events");
    }
    routing_test! { sync sse_filter_accepts_proof_only_filter
        let expr = FilterExpr::Eq(
            FieldPath("proof_backend".into()),
            norito::json::Value::String("halo2/ipa".into()),
        );
        let spec = parse_sse_filters(&expr).expect("proof-only filter should parse");
        assert!(spec.filters.is_none());
        assert_eq!(spec.proof_backend.unwrap(), vec!["halo2/ipa".to_string()]);
    }
    routing_test! { sync sse_filter_params_rejects_invalid_json
        let err = parse_sse_filter_params(Some("not-json")).expect_err("invalid json rejected");
        let _ = err;
    }
    routing_test! { sync sse_handler_rejects_invalid_filter
        let events: iroha_core::EventsSender = tokio::sync::broadcast::channel(1).0;
        let params = EventsSseParams {
            filter: Some("not-json".to_string()),
        };
        let res = handle_v1_events_sse(events, crate::NoritoQuery(params));
        assert!(res.is_err());
    }
}
#[cfg(all(test, feature = "app_api"))]
mod sse_stream_tests {
    use super::*;
    use axum::body::Body;
    use axum::response::IntoResponse as _;
    use http_body_util::BodyExt as _;
    use iroha_crypto::{Hash, HashOf};
    use iroha_data_model::{
        events::{
            EventBox,
            pipeline::{PipelineEventBox, TransactionEvent, TransactionStatus},
        },
        nexus::{DataSpaceId, LaneId},
        transaction::SignedTransaction,
    };
    use tokio::time::{Duration, timeout};
    async fn next_sse_chunk(body: &mut Body) -> String {
        let frame = timeout(Duration::from_secs(1), body.frame())
            .await
            .expect("timeout waiting for SSE frame")
            .expect("stream ended before SSE frame")
            .expect("SSE body frame");
        let data = frame.into_data().expect("SSE data frame");
        std::str::from_utf8(&data)
            .expect("UTF-8 SSE frame")
            .to_owned()
    }
    fn queued_transaction_event(byte: u8) -> EventBox {
        let hash = HashOf::<SignedTransaction>::from_untyped_unchecked(Hash::prehashed(
            [byte; Hash::LENGTH],
        ));
        EventBox::Pipeline(PipelineEventBox::Transaction(TransactionEvent {
            hash,
            block_height: None,
            lane_id: LaneId::new(0),
            dataspace_id: DataSpaceId::new(0),
            status: TransactionStatus::Queued,
        }))
    }
    routing_test! { async sse_stream_expands_pipeline_batches
        let events: EventsSender = tokio::sync::broadcast::channel(8).0;
        let params = EventsSseParams { filter: None };
        let sse = handle_v1_events_sse(events.clone(), crate::NoritoQuery(params))
            .expect("create SSE stream");
        let response = sse.into_response();
        let mut body = response.into_body();
        let hash = HashOf::<SignedTransaction>::from_untyped_unchecked(Hash::prehashed(
            [0x11; Hash::LENGTH],
        ));
        let batch =
            EventBox::PipelineBatch(vec![PipelineEventBox::Transaction(TransactionEvent {
                hash,
                block_height: None,
                lane_id: LaneId::new(0),
                dataspace_id: DataSpaceId::new(0),
                status: TransactionStatus::Queued,
            })]);
        events.send(batch).expect("send batch event");
        let payload = next_sse_chunk(&mut body).await;
        let data_line = payload
            .lines()
            .find(|line| line.starts_with("data: "))
            .expect("data line");
        let json = data_line.trim_start_matches("data: ").trim();
        let value: norito::json::Value = norito::json::from_str(json).expect("json payload");
        assert!(matches!(value, norito::json::Value::Object(_)));
    }
    routing_test! { async sse_stream_preserves_pipeline_batch_order
        let events: EventsSender = tokio::sync::broadcast::channel(8).0;
        let sse = handle_v1_events_sse(
            events.clone(),
            crate::NoritoQuery(EventsSseParams { filter: None }),
        )
        .expect("create SSE stream");
        let mut body = sse.into_response().into_body();
        events
            .send(EventBox::PipelineBatch(vec![
                match queued_transaction_event(0x31) {
                    EventBox::Pipeline(event) => event,
                    _ => unreachable!(),
                },
                match queued_transaction_event(0x32) {
                    EventBox::Pipeline(event) => event,
                    _ => unreachable!(),
                },
            ]))
            .expect("send batch");
        let first = next_sse_chunk(&mut body).await;
        let second = next_sse_chunk(&mut body).await;
        assert!(first.contains(&Hash::prehashed([0x31; Hash::LENGTH]).to_string()));
        assert!(second.contains(&Hash::prehashed([0x32; Hash::LENGTH]).to_string()));
    }
    routing_test! { async sse_lag_is_machine_readable_and_terminal
        let events: EventsSender = tokio::sync::broadcast::channel(1).0;
        let sse = handle_v1_events_sse(
            events.clone(),
            crate::NoritoQuery(EventsSseParams { filter: None }),
        )
        .expect("create SSE stream");
        let mut body = sse.into_response().into_body();
        events
            .send(queued_transaction_event(0x41))
            .expect("send first");
        events
            .send(queued_transaction_event(0x42))
            .expect("send second");
        let error_frame = next_sse_chunk(&mut body).await;
        assert!(error_frame.contains("event: stream_error"));
        let data = error_frame
            .lines()
            .find_map(|line| line.strip_prefix("data: "))
            .expect("stream error data");
        let value: norito::json::Value = norito::json::from_str(data).expect("error JSON");
        assert_eq!(value["code"].as_str(), Some("stream_lagged"));
        assert_eq!(value["dropped_messages"].as_u64(), Some(1));
        assert_eq!(value["replay_available"].as_bool(), Some(false));
        let terminal = timeout(Duration::from_secs(1), body.frame())
            .await
            .expect("terminal stream should not hang");
        assert!(
            terminal.is_none(),
            "lagged stream must close after its error event"
        );
    }
    routing_test! { async sse_idle_stream_emits_heartbeat_comment
        let events: EventsSender = tokio::sync::broadcast::channel(1).0;
        let sse = handle_v1_events_sse(
            events.clone(),
            crate::NoritoQuery(EventsSseParams { filter: None }),
        )
        .expect("create SSE stream");
        let mut body = sse.into_response().into_body();
        let heartbeat = next_sse_chunk(&mut body).await;
        assert_eq!(heartbeat, ": heartbeat\n\n");
    }
    routing_test! { async sse_source_shutdown_is_machine_readable_and_terminal
        let events: EventsSender = tokio::sync::broadcast::channel(1).0;
        let sse = handle_v1_events_sse(
            events.clone(),
            crate::NoritoQuery(EventsSseParams { filter: None }),
        )
        .expect("create SSE stream");
        let mut body = sse.into_response().into_body();
        drop(events);
        let error_frame = next_sse_chunk(&mut body).await;
        assert!(error_frame.contains("event: stream_error"));
        assert!(error_frame.contains("\"code\":\"stream_source_closed\""));
        let terminal = timeout(Duration::from_secs(1), body.frame())
            .await
            .expect("terminal stream should not hang");
        assert!(terminal.is_none());
    }
    routing_test! { async explorer_sse_lag_is_machine_readable_and_terminal
        let events: EventsSender = tokio::sync::broadcast::channel(1).0;
        let sse = handle_v1_explorer_blocks_stream(Kura::blank_kura_for_testing(), events.clone());
        let mut body = sse.into_response().into_body();
        events
            .send(queued_transaction_event(0x51))
            .expect("send first");
        events
            .send(queued_transaction_event(0x52))
            .expect("send second");
        let mut error_frame = next_sse_chunk(&mut body).await;
        if !error_frame.contains("event: stream_error") {
            error_frame = next_sse_chunk(&mut body).await;
        }
        assert!(error_frame.contains("event: stream_error"));
        assert!(error_frame.contains("\"code\":\"stream_lagged\""));
        let terminal = timeout(Duration::from_secs(1), body.frame())
            .await
            .expect("terminal Explorer stream should not hang");
        assert!(terminal.is_none());
    }
    routing_test! { sync explorer_stream_deduplicates_committed_and_applied_heights
        assert!(explorer_height_is_new(None, 7));
        assert!(!explorer_height_is_new(Some(7), 7));
        assert!(!explorer_height_is_new(Some(8), 7));
        assert!(explorer_height_is_new(Some(7), 8));
    }
    routing_test! { async resume_rejection_uses_native_sse_error_contract
        let response = stream_resume_unsupported_response();
        assert_eq!(response.status(), StatusCode::BAD_REQUEST);
        assert_eq!(
            response
                .extensions()
                .get::<crate::ReviewedProtocolNativeError>(),
            Some(&crate::ReviewedProtocolNativeError::StreamResumeUnsupported)
        );
        assert!(
            response
                .extensions()
                .get::<crate::utils::HttpErrorCode>()
                .is_none(),
            "the response boundary assigns the public error code after validation"
        );
        assert_eq!(
            response
                .headers()
                .get(axum::http::header::CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("text/event-stream")
        );
        assert_eq!(
            response
                .headers()
                .get("x-iroha-stream-error")
                .and_then(|value| value.to_str().ok()),
            Some("stream_resume_unsupported")
        );
        let body = response
            .into_body()
            .collect()
            .await
            .expect("collect rejection")
            .to_bytes();
        let payload = std::str::from_utf8(&body).expect("UTF-8 rejection");
        assert!(payload.contains("event: stream_error"));
        assert!(payload.contains("stream_resume_unsupported"));
        assert!(payload.contains("\"replay_available\":false"));
    }
}
#[cfg(all(test, feature = "app_api"))]
mod cursor_mode_tests {
    use super::*;
    use iroha_core::{
        kura::Kura,
        query::snapshot::{CursorMode, run_on_snapshot_with_mode_arc_and_start_budget},
        query::store::LiveQueryStore,
        smartcontracts::isi::query::QueryLimits,
        state::{State, World},
    };
    use iroha_data_model::prelude::*;
    use iroha_data_model::query::{
        QueryItemKind, QueryRequest, QueryWithParams,
        dsl::{CompoundPredicate, SelectorTuple},
        parameters::{FetchSize, QueryParams},
    };
    use nonzero_ext::nonzero;
    use std::sync::Arc;
    fn make_minimal_state(authority: &AccountId) -> State {
        let kura = Kura::blank_kura_for_testing();
        let query = LiveQueryStore::start_test();
        let domains = (0..3).map(|index| {
            Domain::new(DomainId::try_new(format!("cursor{index}"), "world").expect("domain id"))
                .build(authority)
        });
        let world = World::with(
            domains,
            [Account::new(authority.clone()).build(authority)],
            [],
        );
        State::new_for_testing(world, kura, query)
    }
    fn seed_stored_cursor(
        state: &Arc<State>,
        authority: &AccountId,
        gas_budget: u64,
    ) -> iroha_data_model::query::parameters::ForwardCursor {
        let query_params = QueryParams {
            fetch_size: FetchSize {
                fetch_size: Some(nonzero!(1_u64)),
            },
            ..QueryParams::default()
        };
        let request = QueryRequest::Start(QueryWithParams {
            query: (),
            query_payload: norito::codec::Encode::encode(
                &iroha_data_model::query::domain::prelude::FindDomains,
            ),
            item: QueryItemKind::Domain,
            predicate_bytes: norito::codec::Encode::encode(&CompoundPredicate::<Domain>::PASS),
            selector_bytes: norito::codec::Encode::encode(&SelectorTuple::<Domain>::default()),
            params: query_params,
        });
        let response = run_on_snapshot_with_mode_arc_and_start_budget(
            state,
            &state.query_handle,
            authority,
            request,
            CursorMode::Stored,
            QueryLimits::default(),
            Some(gas_budget),
        )
        .expect("start stored query through the authorization corridor");
        let iroha_data_model::query::QueryResponse::Iterable(response) = response else {
            panic!("FindDomains must produce an iterable response");
        };
        let (_batch, _remaining, cursor) = response.into_parts();
        cursor.expect("cursor should be stored")
    }
    fn signed_singular_find_active_abi(
        authority: &AccountId,
        signer: &iroha_crypto::KeyPair,
    ) -> iroha_data_model::query::SignedQuery {
        use iroha_data_model::query::QueryRequest;
        let req = crate::authorize_query_for_test(
            QueryRequest::Singular(
                iroha_data_model::query::prelude::SingularQueryBox::FindAbiVersion(
                    iroha_data_model::query::runtime::prelude::FindAbiVersion,
                ),
            ),
            authority.clone(),
        );
        req.sign(signer)
    }
    fn checked_cursor_mode_keypair(seed: u8, context: &'static str) -> iroha_crypto::KeyPair {
        checked_routing_fixture_keypair(seed, iroha_crypto::Algorithm::Ed25519, context)
    }
    fn query_state(
        authority: &AccountId,
        mode: iroha_config::parameters::actual::QueryCursorMode,
    ) -> Arc<State> {
        let mut state = make_minimal_state(authority);
        state.pipeline.query_default_cursor_mode = mode;
        state.pipeline.query_stored_min_gas_units = 200;
        Arc::new(state)
    }
    async fn run_query(
        state: Arc<State>,
        signed: iroha_data_model::query::SignedQuery,
        opts: QueryOptions,
    ) -> Result<Response> {
        #[cfg(feature = "telemetry")]
        let telemetry = MaybeTelemetry::for_tests();
        #[cfg(not(feature = "telemetry"))]
        let telemetry = MaybeTelemetry::disabled();
        handle_queries_with_opts(
            state.query_handle.clone(),
            state,
            crate::signed_query_test_admission(),
            signed,
            telemetry,
            crate::NoritoQuery(opts),
            crate::utils::ResponseFormat::Json,
        )
        .await
    }
    routing_test! { async stored_mode_insufficient_gas_rejected
        let kp =
            checked_cursor_mode_keypair(0x96, "derive stored cursor insufficient-gas fixture key");
        let authority = AccountId::new(kp.public_key().clone());
        let state = query_state(
            &authority,
            iroha_config::parameters::actual::QueryCursorMode::Stored,
        );
        let signed = signed_singular_find_active_abi(&authority, &kp);
        let opts = QueryOptions {
            cursor_mode: Some("stored".to_string()),
            count_mode: None,
            gas_units: Some(100),
        };
        let res = run_query(state, signed, opts).await;
        assert!(matches!(
            res,
            Err(crate::Error::Query(ValidationFail::NotPermitted(_)))
        ));
    }
    routing_test! { async stored_mode_sufficient_gas_ok
        let kp =
            checked_cursor_mode_keypair(0x97, "derive stored cursor sufficient-gas fixture key");
        let authority = AccountId::new(kp.public_key().clone());
        let state = query_state(
            &authority,
            iroha_config::parameters::actual::QueryCursorMode::Stored,
        );
        let signed = signed_singular_find_active_abi(&authority, &kp);
        let opts = QueryOptions {
            cursor_mode: Some("stored".to_string()),
            count_mode: None,
            gas_units: Some(250),
        };
        let res = run_query(state, signed, opts).await;
        assert!(res.is_ok());
    }
    routing_test! { async stored_mode_continue_uses_cursor_gas_budget
        let kp = checked_cursor_mode_keypair(0x98, "derive stored cursor continue fixture key");
        let authority = AccountId::new(kp.public_key().clone());
        let state = query_state(
            &authority,
            iroha_config::parameters::actual::QueryCursorMode::Stored,
        );
        let cursor = seed_stored_cursor(&state, &authority, 250);
        let signed = crate::authorize_query_for_test(
            iroha_data_model::query::QueryRequest::Continue(cursor),
            authority,
        )
        .sign(&kp);
        let opts = QueryOptions {
            cursor_mode: Some("stored".to_string()),
            count_mode: None,
            gas_units: None,
        };
        let res = run_query(state, signed, opts).await;
        assert!(res.is_ok());
    }
    routing_test! { async ephemeral_mode_unaffected_without_gas
        let kp = checked_cursor_mode_keypair(0x99, "derive ephemeral cursor fixture key");
        let authority = AccountId::new(kp.public_key().clone());
        let state = query_state(
            &authority,
            iroha_config::parameters::actual::QueryCursorMode::Ephemeral,
        );
        let signed = signed_singular_find_active_abi(&authority, &kp);
        // No override and no gas_units → should pass in ephemeral mode
        let opts = QueryOptions::default();
        let res = run_query(state, signed, opts).await;
        assert!(res.is_ok());
    }
}
}
